/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201109-9","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"文教委員会","time":"午後 １時００分～午後 ４時０６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"結局、二重投資を避けるという意味だけで、今回はそちらも一緒にやってしまえということなのか、そこら辺をちょっと、それとも放射２号線をどうしても進めたいので、品川区としては区長が自ら手を挙げて、この道路をやってくれと言ったわけですから、当然、品川区全体としては、この道路を進めたいわけです。だから、放射２号も整備したいから、区が進めたいという意味なのか、そこら辺を説明してください。","respondent":"小林学校施設担当課長","answer":"工事の目的につきましては、擁壁にひび割れが生じたために、安全確保をするためには改修工事を行う必要があると判断して、今回、工事を進めているところです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"逆側なのです。道路がかかっているほうは特に問題が全く見受けられないのですけれども、あえてその問題がないところまで擁壁工事をして、道路のために売る必要があるのですかということなのです。先ほど、二重投資の話もしましたけれども、結局、二重投資は嫌だという、それだけなのですかということと、あと、道路を進めたいという区の全体の意思があるわけではないですか。","respondent":"小林学校施設担当課長","answer":"ここの第二グラウンドの部分につきましては、４周擁壁があって、４周ともひび割れ等がありましたというところで、先ほど言ったように、安全性の観点から改修すると判断したところで、今度はそこに擁壁関係の工作物は建築基準法上、道路という扱いになりますので。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それをなぜやらなかったのかと。やっぱりそれは道路を進めたいということなのですかということと、二重投資は避けるべきだという発言もあったので、そういう意味だけなのではないですかと私は言っているので、もう１回お答えいただきたい。それと、グラウンドの道路用地の部分の売却ですけれども、これは既に行われたのでしょうか。行われたなら、売却はいつなのでしょうか。伺います。","respondent":"小林学校施設担当課長、東野経理課長","answer":"１点目のほうの道路につきましては、先ほども言いましたけれども、擁壁にひび割れが多くあったというところで、補修ではなくて、やり替えを判断しました。道路用地部分の売却ですが、本年６月１８日付で売却を行っております。こちらにつきましては、土地の売買契約と併せまして、その上にありますトイレ、樹木等の移転に係る物件移転補償契約につきましても、同日付で締結をしています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"それと、教育関係整備が教育委員会の仕事なわけですけれども、教育委員会としては、２割減ってしまうことの評価はどういうふうに考えているのか伺います。最後は、陳情にもありますけれども、少年野球の方が、代替地が決まっておらず困っていると書いていますが、代替地は決まっていないのでしょうか。これは必要な措置はすべきだと思うのですけれども、そこについてお伺いします。","respondent":"東野経理課長、小林学校施設担当課長、有馬庶務課長","answer":"この時点までに更地化して都へ引き渡すということで、完了前であるということから、「予定」という言葉を使わせていただいたものです。道路用地の部分につきましては、先ほどもお話ししましたが、建築基準法上の道路という扱いになりまして、先ほど。今回の改修工事についての声ということですけれども、学校のほうからは、児童・生徒の安全のために工事をやってくれということと。","voiceIndex":13,"id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"だから、あえてそういう手法をとらずに、今できるところで、築造ではなく、補修という形でしっかりと安全性も確保しながら整備するということは私はできると思うので、ぜひそういうふうにやるべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"これは、このグラウンドを内側に削る形で新たな擁壁を造るわけですけれども、そこで生まれた空地は、空地のままになるのですか。それともすぐに道路にしていくのですか。それについてを。多分、東京都とそういう話をされていると思うのですが。","respondent":"鈴木都市計画課長","answer":"それまでの間は、通常ですと、道路用地として人が立ち入らないような形で安全性を確保して、ネットフェンス等で囲って管理をするというのが一般的です。","voiceIndex":18,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、これを削ったからといって、誰かが当面の間、何かに活用できるとか、得をするというような話、得というと、ちょっと言葉は悪いですけれども、何かに活用できる形ではなくて、ただ小学校のグラウンドの面積が減ってしまうというのは、常識的に考えて、あるいは社会経済上の利益ということを考えても、あまりいいやり方、プロセスではないというふうに思うのですが。","respondent":"小林学校施設担当課長","answer":"教育委員会としても平成２８年３月頃から擁壁にひび割れが多数あった、それを確認して調査を行い、今回、擁壁のやり替え、改修工事をやるべきと判断したのですが、その間に、放射２号の部分につきましては、平成３０年７月３１日に都市計画道路として指定されました。","voiceIndex":20,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"東京都として、そこまでの緩和ができるのであれば、物凄く大きい擁壁の上に、さらに建物を建ててというようなものは、それは東京都としてもノーと出てくるでしょうけれども、グラウンドの擁壁といった比較的小規模で、その上にさらに建築物を建てる計画がないものについては、これは交渉の余地があったのではないかと思いますけれども、そういうお話は東京都とされたのでしょうか。","respondent":"小林学校施設担当課長、鈴木都市計画課長","answer":"それは擁壁だけではなくて、グラウンドの整備、それと防球ネットの整備、これらを考えますと、かなり高額になってくるものですから、そこら辺のところについても、許可とかそういうものを取って何か月間か。今回はもう既に都市計画決定から事業決定に進んで、さらにその都市計画道路上に、所管の課長も今お話ししましたが、建築基準法上の１項４号という基準法でいう道路の網もかかっているですから、これは東京都と交渉して。","voiceIndex":22,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"この道路側の擁壁というのは、どの程度の危険度、どのぐらいのひび割れでしたか。それがどのくらいたくさんあったのですか。","respondent":"小林学校施設担当課長","answer":"先ほど、補修だとか、そういう話もありましたけれども、そういうものも検討して、その中で総合的に判断した結果、やり替えしかないというところで判断したものです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"そうしたら、いろいろとご答弁がそれぞれあると思うのですけれども、では、区として、あるいは教育委員会として、ここが子どもたちにより長く使えるようにというような視点で何か工夫を試みられたということはあるのですか。そういうことは何もしないままここに至っているのですか。","respondent":"小林学校施設担当課長","answer":"都市計画道路、先ほど都市計画課長からも説明があったところですけれども、指定がされなければ、そういうところも考えられる１つの手法とは思いますが、今回はその間に指定がされて基準法上の道路になりましたので、今回は後退という判断をしたところです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"より住民に理解してもらって行政を進めていくのであれば、やらなければいけないことではなくて、やったほうがいいかもしれないことはやってほしいのです。そうした発想はないのでしょうか。いかがですか。","respondent":"小林学校施設担当課長","answer":"今回は、該当しないということで説明会は開催しなかったものの、先ほどお話ししました２３２世帯の近隣にビラを配って、問合せについては２３件あって、それぞれ個別対応をしているところです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"にもかかわらず、２３２世帯中２３件ということは、改めてこれは住民の皆様方に、今後の説明なり、なぜこういうことをしていて、どういう工事なのかということを改めて、陳情にもありますように、今からでも結構ですので、やはりより多くの方にご理解をいただいて、私は行政として損はないと思うのですけれどもいかがでしょうか。","respondent":"小林学校施設担当課長","answer":"今回は、個別で２３件、これが２３軒のお宅から来たということで、１軒辺り１回で終わっているわけではございません。何回も行ってご説明をしていますので、今回はそういう個別の対応をとったというところでよかったのかなと考えている所存です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"それは複数組み合わせてやっていただければいいと思うし、今回、個別の２３２世帯にビラをまいて、個別に対応したから、これでパーフェクトということではないと思うので、そういった意味でも、多様な方法で説明をするということは、あまり行政が住民をおそれる必要はないと思うので、より多くの人にアクセスしやすい説明は、これからでも構いませんので、やっていったらいかがでしょうか。","respondent":"小林学校施設担当課長","answer":"いろいろなご意見があるとは思いますけれども、現在はそういうものは個別で対応しております。先ほどの条例だ、要綱だというお話で、該当するかしないかというのは、１つの判断材料であって、まずはそれに該当しなかったということも当然検討したところです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"これで最後にしますけれども、今回の個別対応は全く否定していないのです。でも、いろいろなやり方があるのではないですかというお話をしているのですけれども、そんなに説明するのは嫌ですか。そのようなことはないですよね。前向きな何かはないのですか。","respondent":"小林学校施設担当課長","answer":"ただ、それの工事説明会を行うか行わないか、全てに該当するのかというと、またちょっと違うとは思いますので、ご意見として頂戴して、今後、いろいろなところで頑張っていきたいと考えています。","voiceIndex":35,"id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"説明会に関連しまして、今回、条例などの法定義務がないということで説明会を行わないということ、一方、近隣世帯にはポスティングされて個別的な問合せに対応されたということなのですけれども、この陳情者の文章の中に、少年野球で使っている方が代替地がなくて困っているなど、あと、少年サッカーなどの要望も出てきておりますけれども、そうした少年野球とか少年サッカーなど。","respondent":"有馬庶務課長","answer":"学校の利用団体の方、特に少年野球、サッカーの方からは、グラウンドが使えなくなるということで、学校のほうから説明をしています。","voiceIndex":37,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。その際、特にこうした工事に反対だとか、そうした強い否定のご意見とかというのはなかったということですか。","respondent":"有馬庶務課長","answer":"ほかにやる場所がないのかということと、もう１つは、一定程度、グラウンドが狭くなるということで、若干狭くなる部分の影響はどれくらいあるのかというような確認を求められたということはありますけれども、特にそれで反対だとか何とかだという話ではなくて。","voiceIndex":39,"id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"一方、騒音などが生じているということもあって、それにもかかわらず、工事の今後の工程表などが示されていないということなのですけれども、騒音とかが生じているので、今後の工程表とかを表示してあげたほうが、住民の方もご理解が進みやすいのかなということで、今後、工程表などの表示や、また騒音とかで実際に被害を感じられている方のための相談窓口というか、問合せ先というのは。","respondent":"小林学校施設担当課長","answer":"現場の道路面に、事業者の連絡先ならびに１週間の工程表等を掲示しております。","voiceIndex":41,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"確認をしたいのですが、今回の道路用地で売却されるところの面積と、あと幾らなのかということと、あと売るに当たって、今、いろいろと工作物の移転とかという話もありましたけれども、整地とかをした上で売るというふうなルール、公有地を同じ公共団体に売るときのルールといいますか、そこら辺がどうなっているのか確認させていただきたいです。","respondent":"東野経理課長","answer":"道路用地部分の面積ですが、５０５.１７m2です。土地売買代金が５億６,１１９万３,３５３円です。工作物の物件移転補償契約で、こちらは２,９２０万５,６２０円となっています。こちらは、通常、土地の売買に当たりましては、更地で売るというのが原則です。","voiceIndex":43,"id":"exchange-018"},{"speaker":"芹澤副委員長","kind":"質問","question":"理由として、本日ご説明いただいたとおりですが、もともと都市計画道路ありきという話ではなくて、改修をしなければならない、子どもたちの安全性のために改修が必要で、その改修をする際に法的な手続きの中で道路予定地の件でということでお話がありましたので、最後のほうに買戻しの検討というところも書いてありますけれども、そういったことではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"せお委員","kind":"意見","question":"結論を出すでお願いします。不採択でお願いいたします。今、お話にもあったように、既に危険であるほどのひび割れがあるということで、子どもの安全性を考えてのことであるということです。法律の縛りがあるということで、こういった陳情の内容は難しいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"意見","question":"本日、結論を出す、不採択でお願いします。お考え、お気持ちは分からない部分、分かる部分もあるのですが、先ほどからお話があるとおり、安全性の確保の課題を解決しなければならない。法的な位置づけをどうするかという判断の中で、致し方ないのかと思いますので、この陳情については不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、趣旨採択なのですけれども、といいますのは、放射２号線はやっぱり必要ない道路なので、住民も反対していますし、したがって、売却そのものをすべきではないと思うのですけれども、陳情には売るなら一番最後にと書いてあるのですが、陳情者の思いも、タイトルにあるように、売却しないでほしいという思い、この道路に反対という思いなので、せめて行政が率先して売るなという気持ち。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-022"},{"speaker":"横山委員","kind":"意見","question":"ただし、今後、地域の方々へのご説明の際には、個人によって理解の範囲ですとか、捉え方ですとか、その辺りが受け止め方は違うかなというところがあるかと思いますので、相手の方にとって受け止めやすいタイミングですとか、手段、回数、言葉選びなど、お一人お一人の目線に立って、先ほど丁寧にご説明いただいているということでしたので、引き続き、丁寧なご説明を心がけていただくようにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-023"},{"speaker":"芹澤副委員長","kind":"質問","question":"理由として、説明会のところ、まず１点目に、説明会を開いても時間が優先で最後まで聞いてくれないこともあるというふうに記載がありまして、本日の議論の中でも様々な区民に情報を伝達してほしいという話はそのとおりであると思うのですが、学校のグラウンドに関しては、利用者がある程度特定できるのかと思っていまして、周辺の方々、２３０軒近い方々へのご案内等、そのほか、子どもや保護者。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-024"},{"speaker":"せお委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。今回は個別に対応したというお話がありました。そこのところをしっかりとやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"個別の説明会も丁寧にやられているという状況も伺いましたので、また、陳情者の方の、いろいろと聞いています、聞いていますという形になっていて、お聞きされていることをそのままぶつけていただいているのですが、そういう面では、もうちょっとより具体的な部分もあってよかったのかなと思うのですけれども、ただ、いずれにしてもお気持ちは分かりますけれども、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-026"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択です。周辺の住環境や様々な地域のスポーツとか活動に関わることでもありますし、また、地域住民が反対している道路用地の売却にも関わる問題でもありますので、とりわけこの件については、周辺地域住民への丁寧な説明や説明会の開催が私は当然あるべきだと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。住民説明会開催の法定義務はないということもあります。ただし、住民の方に対して丁寧な説明をしていただくというのは、今後もお願いしたいところでありまして、事案によっては住民説明会を開くなどもやっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということで、こちらは趣旨採択でお願いできればなというふうに思っております。ほかの件については具体的な言及はなされていないわけですけれども、少なくともこの件１つとっても、学校という非常に地域の中で関心の高いものについての工事というのは、より広く、あるいはハードルを低く、多くの方が工事について知られるようなことをスタンダードにしていただきたいという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-029"}]},{"id":"topic-02","title":"教育委員会に関わる報告を先に受け、子ども未来部","agenda":"教育委員会に関わる報告を先に受け、子ども未来部","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっと補足で説明していただきたいのですけれども、この調査の時期ですが、１番の６月２９日から７月３１日というのと、２番の令和２年４月という、これはどう関わるのですか。調査を実施したのが６月２９日から７月３１日で、民間給与実態調査の内容（令和２年４月）とある、この４月というのは何をした、あるいは対象なのですか。この４月というのは何をしたのでしょうか。","respondent":"工藤指導課長","answer":"この令和２年４月というふうについてありますのは、直接案内があるわけではないのですけれども、令和２年４月以降のいわゆる月例給等給与がありますので、その給与水準は本年のものという意味で記載があるというふうに考えてあります。","voiceIndex":72,"id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"１番の民間給与の調査というのは、今年の夏のボーナス時期の状況を調べて、月例給については８月から９月について調べた。それで、給与の比較の内容が４月というのは、ごめんなさい、ちょっとまだ理解できていないものですから、コロナの影響を調べるためには、この１にあるように、１つは夏のボーナス、月例給については８月から９月にかけてというのは妥当な時期で、かつ、８月からという……。","respondent":"齋藤教育次長","answer":"民間との比較ということでありまして、この２に書いてあるとおり、どういった企業と比較するかの対象企業は、民間給与実態調査の内容のとおりです。","voiceIndex":74,"id":"exchange-031"},{"speaker":"あべ委員","kind":"確認","question":"今のご答弁は、１番のほうを詳しく教えていただいて、それはそれで大変ありがたかったのですけれども、２番の(1)、これは令和２年４月となっているこの４月の意味がいまだに分からないのですが、対象企業を確定するのが４月ということなのでしょうか。それを確認させていただければと思います。","respondent":"工藤指導課長","answer":"２点いただいたうち、まず、見直しのところにつきましては、本案の勧告は、いわゆる例年、年に１回ですので、現状は年１回のものというところで、頻繁に見直しを行うということは案内されてございませんので、そのように認識しています。","voiceIndex":76,"id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"要は、事業者を選定したものなのかどうかを聞きたいのではなくて、１番と２番の時期のずれ、この４月が何を意味しているのかということが知りたいのです。今はちょっと分からないということでしたら、また後ほど教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"左がこれ、品川区、特別区人事委員会なので違いがあるわけなのですが、それは民間の支給割合を出す際に、特別区人事委員会のほうは２３区での企業の比較、こちらの右側の東京都のほうは、三多摩とか、そういう市のほう、そういうところも入っているから若干低くなっている、こういう考えでいいのかということと、そうすると、今度、いわゆる小中学校の教員の方たちは、区の独自教員でない方以外は。","respondent":"工藤指導課長","answer":"ご指摘いただいたように、都費の教員につきましては、これが妥結した場合に右側の０.１０月が適用されますので、そういった意味では、引下げの幅は、本区でいきますと、固有教員と都費の教員では違っているです。","voiceIndex":79,"id":"exchange-034"},{"speaker":"安藤委員","kind":"確認","question":"労使の交渉状況というのはどのような感じなのかということをそれぞれ伺いたいのと、それと、昨年の同じ時期の文教委員会の報告ですと、いろいろと意見欄がかなりあったのですけれども、今回はシンプルなのですが、それはいわゆるコロナの影響、２回に分けてということで、月例のほうがまだ出ていないからということなのかという確認をしたいのが２点目です。","respondent":"工藤指導課長","answer":"昨年でいきますと、１１月２２日の未明に妥結したということがありますので、目下、来週も含めて交渉しているものというふうには認識しています。","voiceIndex":81,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"教職員の給料に関わる問題です。率直に言って、教師の給料が下がっていくような勧告になってしまうのですけれども、教師の給料は、フィンランドとかを見るにつけて、下げている場合ではないのではないかと思うのですけれども、そこら辺に関しては教育委員会のお考えはどうでしょうか。","respondent":"工藤指導課長","answer":"今委員からご指摘があったところですが、やはり教育公務員であります教員も含めて公務員の給与というのは、こういった公民比較によって決定する仕組みというふうになってありますので、それぞれ使命感に燃えて、学校教育に燃えながらしっかりと教員は勤務していますが。","voiceIndex":83,"id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"４番の給与制度における課題というところですけれども、これはどういった見直しをする必要があるということで課題として挙がっているのかを教えていただけないでしょうか。","respondent":"工藤指導課長","answer":"それによって東京都は２回ですので、配分もちょうど２分の１ですが、そういった見直しをする必要があるというふうに課題として指摘されているです。","voiceIndex":85,"id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"幼稚園教諭ですけれども、公務員だから下がってしまうというのは制度の中で仕方がない部分はあるかとは思うのですけれども、コロナでの保育士の応援金も、幼稚園教諭、公立は対象外になっていたと思うのです。私立は受け取れて、公立幼稚園の先生はもらえません。何かフォローをする、別にお金ということだけではなくて、その必要性は感じられていないのでしょうか。","respondent":"工藤指導課長","answer":"フォローということでご指摘いただきましたけれども、やっぱりそういう意味では、働き方改革の観点からすれば、やはりそれぞれの幼稚園教諭の方もワーク・ライフ・バランス、特にライフが重要であるというふうに見てありますので、そういう意味では、やはり業務の分担であるとか。","voiceIndex":87,"id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"給与というのも１つの大きなメッセージではあると思いますけれども、それ以外に、この状況なので、なかなか公務員の社会からの見え方というのもいろいろとあるとは思いますが、声かけも含めて、様々な形で現場のモチベーションが下がらないように努力していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-039"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"ご説明ありがとうございました。コロナで、品川区のＩＣＴはどうなっているのだろうということをいろいろとご不安の声もいただいていたのですけれども、先日、コロナで突然自宅待機になってしまった学校にお話を伺ってきました。授業がどう変わるのだというようなところの取組みは、どういうふうに進めてきて、今どのくらいの段階に来ているのでしょうか。","respondent":"工藤指導課長","answer":"ですので、今そういった説明の中では、今はこのようなソフトが入りますという研修をしていく中で、私どもは、まず第一弾として、そうは言っても、まず初めにここからやりませんかという案内を第一弾は先週末に教員に示したところで、ロイロノートで書くとか、配付する、集める。","voiceIndex":95,"id":"exchange-040"},{"speaker":"あべ委員","kind":"質問・要望","question":"あまり長くならないようにします。文部科学省でＧＩＧＡスクールとしてこれの導入が一気に進んだわけですけれども、やはりこれは、文部科学省だけの思惑ではもちろんなくて、ＧＩＧＡスクールで１人１台というところまで一気に進んでいくには、経済産業省の「未来の教室」の動きが強力な後押しになったかと思います。体制みたいなものをつくっていらっしゃるのですか。","respondent":"工藤指導課長","answer":"そういったことも可能になることで、その子が興味を持ったことがすぐに調べられて、それで解決していく、また疑問があれば教員に聞くであるとか、学びを構成していくこともやはり可能になっていくということは、やはり柔軟に。","voiceIndex":99,"id":"exchange-041"},{"speaker":"あべ委員","kind":"質問","question":"それともう１つは、実践が進んでいくと、やっぱり教員の異動によって、また新しい先生方が毎年春に入ってくるとなると、そこのシステムといったらいいのですか、自治体ごとに随分と違うソフトを使ったり、違う使い方をすると思われますので、それを入ってきた先生に早急に品川区なら品川区のシステムに慣れていただいて、そこで指導していただくというのは。","respondent":"工藤指導課長","answer":"教員の異動に関しましては、やはり品川区に来た教員が品川区のタブレットをすぐ使いこなせるようになっていることが望ましいと思いますが、そういった意味では、私どもが今、教員向けのスタートカリキュラム、「はじめてカリキュラム」というものを作っておりますが。","voiceIndex":101,"id":"exchange-042"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、電子黒板は、もう全部の学校で導入済みということでよろしいのかということと、あと、こうしてタブレットが普及してきますと、教師もタブレットを持っている、タブレットですと、生徒は手元で自分の見たいところを見るとか、そうしたことになってくるのかと思っているのですが、そうすると、電子黒板とタブレットの関係性というか、電子黒板も活用できると思うのですけれども、今後。","respondent":"篠田学務課長","answer":"電子黒板の普及状況ですけれども、委員ご案内のとおり、全ての学校の全ての普通教室には入っています。それから特別教室も、最終的に今年度中には全て入る予定であると、特別支援学級の教室にも全部配備が終わる予定です。","voiceIndex":103,"id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"ＩＣＴ研修員という方がいるのですけれども、やっぱり今でさえすごく大変な職場のところに、新たなスキルを身につけるというのはなかなか大変だと思うのですが、ＩＣＴ研修員の方は、やっぱりそういう負担をかなりやわらげてほしいというか、援助はするべきだと思うのですが、これは増やすべきだと思うのですけれども、増やす予定はあるのか。","respondent":"篠田学務課長、工藤指導課長","answer":"来年度以降、そちらをさらにもっと手厚くできないかということで、各学校、週１回ぐらい回れればいいなということで、今、検討をしているところで、予算要求もしているという状況です。それは私どもがチェックするしないではなく、教員自身がそういったことを目標にして進めていただきたいということで、学校のほうには指導してまいりますし、そういった意味では、一定程度、先進地区の事例であるとか。","voiceIndex":105,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。目とかに対する健康への影響が不安視、やっぱりどうしても指摘されるのですけれども、そこら辺については、何か区としては子どもたちの健康への影響を少しでも軽減するような配慮というか、あるいは方策というか、検討みたいなものはあるのでしょうかというのが１つです。それも伺います。","respondent":"篠田学務課長、工藤指導課長","answer":"それと、運用時間、子どもたちが際限なく使うことのないように、そういった部分をきちんと、各学年ごとに利用時間等が変わってくると思いますので、それを今、検討していますけれども。ですから、一様に課題が増えるということではなく、個に合った家庭学習も可能になるというところが示されているところですので、そういった活用を図りたいと考えているところです。","voiceIndex":108,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"この資料にもありますが、協働学習の充実と個別最適化した学びというのが並んでいるのですけれども、個別最適化した学びというと、何かすごくいいことのように聞こえるのですが、協働学習というか、そもそもどういうふうにこれからの時代に求められる学びを実現するのかという視点がないと、個別最適な学びというのが。","respondent":"工藤指導課長","answer":"ですから、協働学習もやはりこれまで行えなかったことがよりできていくだろうというふうに思いますので、そういった効果的な事例を各学校に示し、また共有し、進めていきたいと考えておりますので、そのようなところで今後の取組みについてになってしまいますけれども。","voiceIndex":111,"id":"exchange-046"},{"speaker":"たけうち委員","kind":"質問","question":"１点、ＩＣＴ推進教員について、役割は何となく分かるのですが、役割ですとか、あと、もう全部の学校で１人とかが決まっているのかとか、人選はどういうふうにしているのかとか、あと先ほども言ったＩＣＴ研修員の方との関連、例えば連携をどうとっていくのかとか、その辺のことを教えてください。","respondent":"工藤指導課長","answer":"ＩＣＴ支援員等との連携につきましては、特に授業改善のところで機械等の使用の仕方であるとか、今後、ｉＰａｄが配備されたところでは、やはりその連携が必要であるというふうに思っていますので、そういった連携は進めていきたいというふうに思ってあります。","voiceIndex":113,"id":"exchange-047"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。いろいろな学校の先生の中から、ＩＣＴ推進教員の方がいろいろなことを聞かれたりして、それに対応していくとかということが増えてくるのかなというイメージがある中で、負担軽減とか、まだ始まっていないのだとは思うのですけれども、今後、そういう方たちに対するフォローとか、そういうものはどのように教育委員会として考えているのかを教えてください。","respondent":"工藤指導課長","answer":"そういった意味では、様々必要な情報であるとか、私どもはＩＣＴ推進教員の声も十分に活かしながら、推進教員の人たちが学校の中で進める上で必要な情報を常にやり取りしながら、その推進教員に任せきりにならないように。","voiceIndex":115,"id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いします。ロイロノートの特徴を、どうしてこのようなシステムを選んだのかということを、簡単で構いませんので教えてください。３ページですけれども、ＩＣＴ推進教員とＩＣＴ推進リーダーという２種類が出てくるのですが、推進教員の中でリーダーがいらっしゃるというようなことなのでしょうか。こちらのご説明をお願いします。","respondent":"工藤指導課長、篠田学務課長","answer":"ＩＣＴ推進リーダーと申しますのは、校長会を通じまして、推進教員というのは各校１名、各校の推進役なのですけれども、推進リーダーというのは。基本的に今考えているのは、学校内ではＷｉ－Ｆｉを使ってつなぐ、それ以外のところはＬＴＥ回線を使うということになってありますので、外の環境ですと、Ｗｉ－Ｆｉの環境整備がなかなか難しくなってまいりますので。","voiceIndex":117,"id":"exchange-049"},{"speaker":"せお委員","kind":"質問","question":"１点お聞きしたいのですが、最後にあります研修のロードマップのところで、先ほどから個別最適化された学びということで、ＧＩＧＡスクール構想がそういったものを進めていくということなので、やっていかれると思うのですけれども、研修の中で、このお子さんにこの学習の教材が適しているとか、そういうことは教員側が見つけるというか、判断するのはすごく難しいと思うのですが。","respondent":"工藤指導課長","answer":"そういう意味では、例えば教員が、自分が担当している児童・生徒に対してそれぞれどのような教材が適しているかというのは、一定程度、私どものほうから、アプリの紹介だけではなくて、活用の事例とかも含めながら、また区内の推進校での先進事例もありますので。","voiceIndex":120,"id":"exchange-050"},{"speaker":"芹澤副委員長","kind":"質問","question":"何点かあるのですが、この３枚目のＳＮＳ学校ルール研修というもので、ＳＮＳルール研修というのは、例えば情報モラル教育と前のページにもありますけれども、こういうところが関わってくるのかと思いますが、まずこの情報モラル研修というのは、子どもたちに対してはどのようなことを、どの場面で教えていかれるのかということと、あと、そもそもお配りするタブレットに関しては。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目のＳＮＳの指導についてです。こちらにつきましては、タブレットを導入する以前から、今年も行っております。例えば、学校ごとに独自のアプリで指導をしたいといったことがあれば、一定の手続きをとって、その学校ごとに入れるというような対応はありますけれども、一人ひとりが好き勝手に入れてしまうのは、セキュリティの問題もありますので。","voiceIndex":123,"id":"exchange-051"},{"speaker":"芹澤副委員長","kind":"質問","question":"もう１点、先ほど、全ての教科で使っていくというようなお話があったと思うのですけれども、例えば体育とかでも使われるご予定があるのですか。","respondent":"篠田学務課長、工藤指導課長","answer":"あくまで学校として何かの教科でこういったものが必要だということで、申請が組織としてあったときには対応していきたいです。体育の中でも言語活動と申しまして、やはり振り返ってまとめるであるとかというのはタブレットを使うことも可能になりますので、そういった活用は体育に限らず全ての教科において。","voiceIndex":126,"id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"先ほどの議論の中でＩＣＴ推進教員の話が出ていて、ちょっとお伺いしたいと思います。年度途中ということで、本年度は時数については考慮されないということだったのですけれども、来年度以降も時数など、持ち時間を減らさずにＩＣＴ推進教員はこの業務に当たっていくということなのでしょうか。あえて聞きますけれども、手当の対象などになるかどうかということも教えていただければと思います。","respondent":"工藤指導課長","answer":"そういった意味では、いわゆる手当でありますとか、持ち時数軽減というのが制度上あるわけではございませんので、本年度は年度途中の指名ということでしたので、いわゆる校務分掌の１つというふうに私どもは考えてありますので、次年度以降につきましては。","voiceIndex":129,"id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"校務分掌に位置づけられるというのは、それを聞いてちょっとほっとしたのですけれども、ただ、ＩＣＴの分野は、それがどのくらいの分量であるか分からずに仕事だけ渡されるということも企業ではままあることで、ＩＣＴ推進教員に、では、ＩＣＴのことは全てそちらへということで業務量が集中してしまうようなことがあっては、やはり学校運営上よろしくないと思うのですけれども、そこのところの業務量の管理。","respondent":"工藤指導課長","answer":"私どもは、やはりＩＣＴ推進教員が進める、あるいは、その方だけが進めるというふうにはもちろん考えていないところです。ですので、学校の中の活用を検討する組織、いわゆるチームを学校の中に設置していただいておりますので、あくまでもその中心であるという扱い。","voiceIndex":131,"id":"exchange-054"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"そういう経済的に厳しい方はこれが見られないというのも、なかなか教育委員会としては手当てをされたほうがいいのではないかと思う１つの課題だと思うのですけれども、例えば、教育総合支援センターに来られたら、この期間中に視聴できるとか、何かそういう見られない環境の方をフォローするアイデアみたいなものはありますでしょうか。","respondent":"有馬庶務課長","answer":"今回につきましては、ここの講堂で収録をするということでして、希望者があれば、１１月２０日の収録日に講堂でも、各ＰＴＡの会長を中心に数名なら大丈夫ですということで意見を伺っているです。","voiceIndex":139,"id":"exchange-055"},{"speaker":"あべ委員","kind":"意見","question":"皆さん、ＰＴＡだと、来られた方は記憶があると思うのですけれども、各校何人と割当が来て、交通費をもらって行くというような感じだったと思いますので、これはオンライン開催というだけでもかなり前進だと思います。いろいろと工夫をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-056"},{"speaker":"横山委員","kind":"質問","question":"これの所要時間はどのくらいなのでしょうか。対面での講演会は、今までは質問とかを受け付けていたのではないかと思ったのですけれども、オンラインの場合、質問ですとか、アンケートですとか、そういったところはどういうふうな運用でやられるのかを教えてください。","respondent":"有馬庶務課長","answer":"基本的に時間はいつもは１時間半とか、質疑を入れてということですけれども、それだとずっとオンラインを見ている方は若干長いかなと思いますが、おおむね、７０分程度お話ししていただける予定です。","voiceIndex":142,"id":"exchange-057"},{"speaker":"芹澤副委員長","kind":"質問","question":"細かいところなのですが、「手話通訳があります」と一番下に書いてあって、必要だと思うのですけれども、ＹｏｕＴｕｂｅは、変な設定をしなければ、基本的に字幕もついているようなイメージがあるのですが、字幕も併用して使っていただけるような動画になる予定なのでしょうか。","respondent":"有馬庶務課長","answer":"字幕は最終の確認はとれておりません。","voiceIndex":145,"id":"exchange-058"}]},{"id":"topic-05","title":"に戻りまして、(2)旧第一日野小学校跡地を活用した区立保育園・児童センター等の改築","agenda":"に戻りまして、(2)旧第一日野小学校跡地を活用した区立保育園・児童センター等の改築","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"基本的には、これは区民の財産である学校跡地なのです。地域からは、特養や保育園、公園などの整備を望む住民要望もありました。伺いますけれども、旧第一日野小学校跡地の活用以外に手法は何かなかったのかというか、これ以外の建て替え手法は、機会を逃すとかなり困難になるというご説明もありましたけれども、検討をしたのかどうか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"保育園の建て替えにつきましては、この近辺の保育園の建て替えの元として使えないかということで検討してきたところです。現在、この間の検討の中で、第一日野小学校跡地が、暫定活用の中で使えるという話になったことから、こちらを使わせていただく次第です。","voiceIndex":153,"id":"exchange-059"},{"speaker":"安藤委員","kind":"確認","question":"一応、今のご答弁は、ここ以外の建て替え手法も検討したということでよろしかったのでしょうか。で確認しますので、ご答弁ください。分かれば、オアシスルーム・ポップンルームのほうの仮設建物についてもなのですけれども、これは資料には２０２６年以後に「解体」という文字がないのですけれども、これはさらに使い続けるというお考えなのでしょうか。それも伺います。","respondent":"吉田保育施設調整担当課長、若生保育支援課長","answer":"そのために、今回、こちらの用地があることから、その用地を使って建て替えを進めようとしています。それから２０２８年以降ですが、暫定活用期間までしか現在検討しておりません。こちらは荏原複合施設内の大規模改修に伴っての移転になりますので、基本的にこの両ルームについては、改修後に戻るということで、ただ、仮施設について解体するかどうかというのは、今後の全庁的な検討も含めた動向については。","voiceIndex":155,"id":"exchange-060"},{"speaker":"安藤委員","kind":"確認","question":"もう一度、そこは確認させてください。それと、今回の仮設建物ですけれども、それぞれ建物を２つ造るということですね。それは現時点でどのようなものを考えていらっしゃるのでしょうか。それぞれの平米数、それぞれの建物の敷地面積の平米数、あるいは延べ床面積、どれぐらいと考えているのか伺います。","respondent":"吉田保育施設調整担当課長","answer":"２０２８年以降の保育園のというお話ですけれども、暫定活用後につきましては、保育園の利用については決まっていないです。それから、施設の平米数についてということですけれども、まだ基本設計の段階ですので、細かいところは決まっていないところです。","voiceIndex":158,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"この解体というのは、暫定活用以降、またこういうような形で使うかどうかというのは決まっていないので、逆に言うと、また新しく使うということもあるということなのでしょうか。そこら辺について、答える方はいないと思うのですけれども、子ども未来部としては、それ以上の余剰の土地を使ってさらに何か考えていることはあるのでしょうか、ないのでしょうか。伺います。","respondent":"吉田保育施設調整担当課長","answer":"失礼いたしました。今回の保育園の建て替えとしましては、暫定活用の期間としては、その間で建て替える予定としては２年の改築を予定しておりますので、２年の改築後は解体するというところまで考えているところです。","voiceIndex":160,"id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"それで、まず１つ、このオアシスルームの立地がこちらに移ってくることによって、荏原地域のバランスがどうなるのかというのを教えていただければと思います。それから保育園ですけれども、建て替えをした後の規模はどの程度になるのか、もちろん決まってはいないでしょうけれども、現状と同じ規模しかあり得ないのか、それとも少し定員を増やすようなことも検討されるのか教えてください。","respondent":"若生保育支援課長、吉田保育施設調整担当課長","answer":"荏原複合施設内のオアシスルーム等の移転後の荏原地域のオアシスルームのバランスです。荏原地区は、現在、荏原保健センター内オアシスルーム以外には、２年前に開設した平塚ゆうゆうプラザのオアシスルームがあります。保育園の建て替え後の規模ですけれども、来年度から基本設計を進めていく予定です。そのため、その中でどのぐらいの建物が建てられるのかとか、その辺の検討をした上で、また考えてまいるところです。","voiceIndex":162,"id":"exchange-063"},{"speaker":"あべ委員","kind":"質問・要望","question":"今の定員にとらわれることなく、移転後の定員に合わせた形でこの規模をつくっていただきたいと思いますが、その考えについてお伺いしたいと思います。それと、２つ建物が建つことになると思うのですけれども、小学校の跡地はかなり広いと思うのです。この２つの、つまり複合施設のほうと、保育園の建物、それを除いた敷地的な余裕はどの程度あるかというのは把握されていますか。","respondent":"吉田保育施設調整担当課長","answer":"３点のご質問をいただいたと考えています。建て替えで戻ってきた際に定員を増やすということにつきましては、建て替えの際の基本設計でどのぐらいのものが建てられるかというところで検討しながら、また保育需要等を鑑みながら検討していくところだと考えております。","voiceIndex":165,"id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"新しい建物の規模が決まらないのに、こちらだけ増やすわけにはいかないとは思いますので、そこはバランスを見ながら、できるだけ定員を確保できるような方向で検討していただければと思います。残りの面積については、確かに企画のほうで把握されていると思うのですが、１つお願いしたいのが、やはり保育園について、距離が遠くなってしまうご家庭がかなり出るのではないかと思います。いかがでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"今後の基本設計を進めていく中で、検討して、どの辺までできるのかは、また調整、検討をしてまいりたいと思います。","voiceIndex":167,"id":"exchange-065"},{"speaker":"たけうち委員","kind":"質問","question":"このいただいている図で、一番下の荏原複合施設からの距離と時間が抜けているのかと思うのですけれども、大体東五反田と同じぐらい、数百ｍ、１１分ぐらいと考えていればいいのですか。抜けているのか、あえて抜いているのかちょっと分からないですけれども、分かりますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-066"},{"speaker":"せお委員","kind":"質問","question":"２点お聞きしたいのですけれども、１点目が、私が勉強不足で申し訳ないのですが、まず最初の経緯のところに、貸付が令和４年９月に終了するとあるのですけれども、これは法律とか契約とかいろいろとあると思うのですが、これが早まることはあるのですかというのが１点です。","respondent":"吉田保育施設調整担当課長、立木保育課長","answer":"東五反田保育園につきましては、建て替えが少し先になりますので、こちらにつきましては、来年度の４月に入る０歳児までは影響が出ないことになります。東五反田保育園の説明会につきましては、１１月２７日を予定しています。これから入園を希望される方に関しましては、窓口のほうで、今後こういった計画がありますということで、別紙で用意いたしまして、ご希望されて入った後に知らなかったということがないように説明をしています。","voiceIndex":172,"id":"exchange-067"},{"speaker":"せお委員","kind":"意見","question":"すみません、貸付のほうは所管が違うという解釈だと思います。失礼しました。説明のほうも、ひろまち保育園のこともあったと思いますので、ご丁寧にというのと、あと、対応した職員で言うことが異ならないように、一貫した説明をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":175,"id":"exchange-068"}]},{"id":"topic-06","title":"医師・看護師の保育園入園選考における調整指数加点","agenda":"医師・看護師の保育園入園選考における調整指数加点","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"請願審査のときは、たしか特に国からも通知とかはないという話だったと記憶していますけれども、その後、国からの指針みたいな、何かそういうものが出たりとかというような状況はあるのでしょうかということと、それと今回、医師と看護師のこういう加点ということでやっているところは、もし分かれば、他区とか、ほかの自治体の状況とか、分かる範囲でいいですけれども教えてください。","respondent":"立木保育課長","answer":"国からの通知は、その後も特に出ておりませんので、前と状況は変わってございません。それから、他の自治体ですが、平塚市で優先利用という形でやっているということで、特別区、東京都下には今のところ話を聞いているところはございません。","voiceIndex":180,"id":"exchange-069"},{"speaker":"あべ委員","kind":"確認","question":"一応確認ですけれども、これはご両親のいずれかが医師または看護師であれば適用されるということで、その医師の配偶者の職業は問わないということですね。もちろん保育園ですから、加点ですし、必ずということではないと思いますけれども、１点そこを確認します。","respondent":"立木保育課長","answer":"委員おっしゃるとおり、どちらかが医療従事者であれば１点加点という形をとらせていただきます。","voiceIndex":182,"id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"どこで線引きするかというのは本当に難しい問題かとは思うのですけれども、それはそれでやっぱり思いとしてはすごく分かるのですが、区としては、どのような考えかということと、それから当面の間の時限措置となっている、この当面の間のイメージなのですけれども、本当にこの４月、とりあえずはこの４月だけということなのか、少なくとも年度内はということであるのか、でも、コロナが落ち着くのは。","respondent":"立木保育課長","answer":"医療提供体制の逼迫というところを１つキーワードにいたしまして、その際に、やはり必要とされる職種というところで、直接治療に携わる、接触するというところで、医師・看護師に注目をさせていただいたという次第です。","voiceIndex":184,"id":"exchange-071"},{"speaker":"あべ委員","kind":"意見","question":"となると、やっぱりある程度の期間になるかというふうに思います。すごく短いのであれば、職種の間口を広げてもいいのかなと思いましたし、やっぱり何年単位となってくると、職種もかなり絞ることになるのかと考えておりましたので、当面、推移を見ながら、また状況が変われば、これについては改めて見直しも考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":186,"id":"exchange-072"},{"speaker":"たけうち委員","kind":"質問","question":"今のことに関連するのですが、１１月２日から案内を開始されて、またホームページ等でも出されているということで、今のところ、これに対する何か区民の方からの反響というか、声ですとか、場合によっては苦言とか、そういうものが来ているかということと、それから、これは分かればで結構なのですが、今、同じような形で既に保育士に加点されていますけれども、その１点の効果というか。","respondent":"立木保育課長","answer":"そのうち内定になった方が４２名ということで、１点加点されましたけれども不承諾になりましたという方は１３名ということで、申込みに対しては７６％ほどの方が１点加点によりまして内定が決まっているというような状況です。","voiceIndex":187,"id":"exchange-073"},{"speaker":"たけうち委員","kind":"質問・要望","question":"区民の方からまたいろいろなお声が出てくる、さらにこれから見られる方が、そうすると、さっきお答えになられたように、今回、医療提供体制を確保するという観点で絞ったのだということを丁寧にお答えいただきたいのと、併せて、今、後段のほうは、それぐらいまでの統計しか多分とりようがないと思うので、いわゆる１点が活きて逆転して内定したというところまでは多分つかめていないのだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":54016,"voices":190}},{"id":"r02-20201109-5","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"総務委員会","time":"午後 １時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議事運営の関係上、取り上げる順番を変更し、初めに(3)ふるさと納税（寄附金）に係る体験型返礼品の追加","agenda":"議事運営の関係上、取り上げる順番を変更し、初めに(3)ふるさと納税（寄附金）に係る体験型返礼品の追加","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"寄附金額についてですが、資料にも５番目として書いてありますけれども、５万円以上で、品川区民からの寄附には返礼品がないと、これは原理原則で、法律的にもそうなっているのかと思うのですが、何か工夫して、返礼品はないけれども、例えば後で、寄附してくださった方のみを対象にするか云々は別として、産業振興という意味合いで、品川区の産業振興に協力してくださいというような観点から。","respondent":"伊東税務課長","answer":"特例控除の適用がないという形での寄附に対してであれば、それはふるさと納税とは離れますので、可能かとは思うのですけれども、なかなかそういう制度というか、辞退したからいいという話ではないのかと。この制度下では、ちょっと難しいかなと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区では、既に二十数億円という額が、区民税の自然減ということでなくなりつつあると。まして、これから１年半後、品川区もより厳しい状況を迎えてくるようならば、何か抜本的な対策をしていただきたいと私は思います。これについて答弁してくれとか、そういうのではなくて、意見として検討していただきたいということを申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"５万円以上寄附してくださった方ということなのですが、そもそも、ここは、うちのすぐ近所なのでたしか看板だけは見にいったのですが、普通に使おうと思ったら、それなりにお値段というのですか、料金がかかると思うのですが、一般利用とこのふるさと納税では内容に少し差があるのか、例えば一般利用だったらパイロット制服の着用は無料ではないけれども、これだったらできるよというようなことがあるのか。","respondent":"伊東税務課長","answer":"一般利用は別途料金がかかります。それと、一般利用にも様々メニューが用意されているのですけれども、フライト時間に限って考えますと、１５分から１２０分という形になっていまして、今回想定したのが３０分というところで、一般的には１万２,０００円かかるです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"これだったら寄附の返礼品としてすごくお得感というか、そういうのがあると思われたとしても、行くのがちょっと不便だったりすると、利用しようと思ったけど実際はできないとかいうようなことがあると、繰り返しの利用とか、そういうことも難しくなるのかなと思うのですけれども、その辺のお金ではないサービスみたいな、ここまで行くのにどういう手段がありますとか、そういうご案内とかは。","respondent":"伊東税務課長","answer":"反応をリサーチというか、調べたかということだと思うのですけれども、こういう施設は国内に数少なく、たまたま品川区内の施設ということで、珍しいため、一定の興味を持っていただける方もいらっしゃるのかなと思い、あと、時間は１５分からあるといいましたけれども。","voiceIndex":10,"id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"体験型返礼品ということで、フライトシュミレーターの操縦というのは大変すばらしいと思うのですけれども、私がぱっと思いついた体験型というと、区役所の隣のスポル品川のサーフィンですか、ああいうのもすごく人気があって、スポル品川自体がなくなってしまう施設なので、私は個人的に貴重なのかなという感じなのです。","respondent":"伊東税務課長","answer":"以前から、屋形船ですとか、そういうのも考えていたところですけれども、なかなか時期的に、来年以降と考えていたところでございまして、ほかの体験型云々というのは、情報がなかなかない中で、スポル品川も確かにあろうかと思うのですけれども。","voiceIndex":12,"id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"こちらは何名、１人ということなのでしょうか。食料品だと何人前、物だと何人分とかいうので大体分かるのですけれども、これは、１人に対する返礼なのか。最後に、ふるさとチョイスは返礼品の数なんかも多分国内で一番多いサイトなのかなと思うのですけれども、もう１つの東急ふるさとパレットを選んだ理由を教えていただければ。","respondent":"伊東税務課長","answer":"返礼品に関して、食料品等々は都市部ではなかなか難しいというところがあって、しながわ土産的なものは一部入れておりますけれども、なかなかそれ以上のものはお返しできない状況です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問","question":"今、ご質問させていただきましたけれども、一般の方も、１人だけなら１人でいいけれども、家族もついていっていいのかなとか、そういったことは多分気になると思います。日程変更も常識の範疇で可とか、そういう感じで、返礼品として載せるときには、そういうことも一言添えるといいのかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。再度確認させていただきたいと思います。先ほど課長のご答弁では予約は取れるというお話でしたが、優先的に取ることが、品川区と事業者の中でそういうところまで契約の中にあるのかというところを教えていただきたいと思います。","respondent":"伊東税務課長","answer":"現在は数的には落ち着いているというような状況もあると聞いております。それと、優先予約という形までは交渉できていないという状況です。先着ではないですけれども、一般予約と同じように、お客さんと会社の間でやっていただくものです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"すいません、先ほどは奥歯に物が挟まったような言い方をしてしまったのですけれども、今の副委員長のご質問に重なるところもあるのですが、アクセスが不便と言ったのは、あのビルで独自のバスを出しているのです、品川ルートと五反田ルートと。あれは一般の人は乗せてもらえないのだと思うのです。不動産屋だったら徒歩１０分と当然書きますが、やはり、ちょっと不便なのです。それについては意見でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"１件だけなのですけれども、これだけ歳入不足の傾向が続いていて、特にふるさと納税に対する対応策とか、そういうことを考えるチームを企画や財政の部署で作るお考えはないのですか。そうすると、品川区は、出しているのだけれども、かなり小粒なものが多いので、その辺、企画や財政として何か対策を考えなくてもいいのですか。それとも今後、そういうチームを作ろうというお考えはあるのですか。","respondent":"佐藤企画調整課長","answer":"企画調整課内で、ネーミングライツも含めて、様々な形の歳入確保については常日頃から検討して、調査・分析しています。委員ご指摘のとおり、歳入は二十数億円、ふるさと納税に持っていかれている現状もありますので、またさらに積極的に検討を進めていきたいと考えております。","voiceIndex":22,"id":"exchange-010"}]},{"id":"topic-02","title":"ＥＳＧ債購入に伴う投資表明","agenda":"ＥＳＧ債購入に伴う投資表明","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"環境施策の推進ということで、新たな債券を購入したいという報告でありますが、運用方針にもある安全性を最優先にというところを確認させていただきたいと思います。つまり、元本の保証はあるのか、元本割れの危険はないのか、安全性についてご説明を頂きたいと思います。","respondent":"中山会計管理者","answer":"安全性についてのご質問です。今回の東京グリーンボンドは元本割れしないということになっておりまして、ムーディーズとかの投資格付でもＡプラスということで、国債と同様の格付がされているものです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"お聞きします。そして、１０月に発行しているこの債券ですけれども、既に完売しているということで、相当スピードも速くて、我々議会に提出する余裕もなかったかとは思うのですが、もう一度繰り返しますけれども、債券なので危険がある以上は慎重にやってほしいと私は思うのですが、ご見解をお聞かせください。","respondent":"中山会計管理者","answer":"品川区公金管理運用方針には、購入できる債券としまして、国債、政府保証債、政府関係機関債、そして地方債ということになっております。東京都の債券ということで、この地方債のところに合致しているものということになっています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"繰り返しますけれども、「東京都債券への投資判断に必要な情報は全て販売を担当する銀行・証券会社等から入手してください」と出ていますので、東京都とは切り離されているとしか考えられないのです。今回、もう購入してしまったのでしょうけれども、できれば、いろいろな意味で、経済状況が不安定なときなので、私は慎重に対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。今、須貝委員も話したのですが、発行日が１０月２７日ということで、区としてももう債券を購入したという考え方でいいと思うのですけれども、この中で、特別区、他区はどういう状況になっているのか分かれば教えていただきたいのと、ホームページで公表すると説明がありました。","respondent":"中山会計管理者","answer":"ホームページでの表明ですが、東京都発行の東京グリーンボンドへの投資についてということで、今回ＥＳＧ債を購入したこと、それから、今後も、まずは安全性、運用効率を第一に考えながらも、ＳＤＧｓ債。","voiceIndex":34,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"今回のグリーンボンドで調達した資金の代表的な充当事業が２つが挙げられているのですが、代表的なということですので、ほかにもあると思うのです。できたら、もう少し具体的にどんなものに対して充当するというのが分かるといいと思うのですが、それは公表されていないのでしょうか。教えてください。","respondent":"中山会計管理者","answer":"東京都のホームページの中にグリーンボンドの発行方針というのがあります。これの一番最後の５ページ目のところを見ていただくと、２０２０年度と２０１９年度の主な充当事業が載っています。この丸がしてあるのが今回のグリーンボンドの対象ということになります。","voiceIndex":37,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺は、リンクを張るのか、品川区として独自に情報を出すのかはご判断いただきたいと思いますが、こういうことに関心のある人は、本当にそれが環境対策になっているのかということまで追求したいと思うのです。その辺、ぜひ情報は出していただいたほうがいいかなと思いますので、よろしくお願いします。これは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"２点お伺いいたします。品川区のホームページにどういう形でこれから載せていただけるのか、まだ分かりませんが、お知らせのところにこういうことをしましたという形ではなくて、できれば、本当であればＳＤＧｓの取組というような１つのコンテンツがあって、そのページで品川区がこういうことをしているのだというぐらいやっていただければなと思いますが、今後、そこもぜひご検討いただきたいと思います。","respondent":"中山会計管理者、佐藤企画調整課長","answer":"私のほうは、２点頂いたうちの最初の資金の件についてご説明いたします。今回のこの１億円は減債基金から購入するものになります。ホームページの記載に関しましても、新長期基本計画の安全の施策の柱の中に、地球環境にやさしいまちづくりというのが記載されていますので、そういったものとリンクして。","voiceIndex":40,"id":"exchange-017"}]},{"id":"topic-03","title":"所管事務調査、シビックテック","agenda":"所管事務調査、シビックテック","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"シビックテックは進めていくべき事業だと私も思います。どうしても今、品川区の事業を見ても、やはり個々に対面したり、現場に行ったりして、話を聞いて、問題点を現地に行って確認するというのが基本の考え方だと思うのですが、その辺についてどのようにお考えでしょうか。","respondent":"山本情報推進課長","answer":"むしろ電子の申請ができる方はそちらを使っていただいて、その分、職員のマンパワーが浮いた分は、デジタル技術を活用できない高齢者の方への対応等を充実していく、そういった形で進めていければいいなと考えているところです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"須貝委員","kind":"確認","question":"今回、接触確認アプリＣＯＣＯＡというアプリが出て、これが普及すればいいのですけれども、思ったより普及しないという問題も生まれていると思うのです。","respondent":"山本情報推進課長","answer":"それ以外にも、運用側の問題といいますか、安定して継続して運用していくためには様々な課題があるというところで、区としましては、運用している方たちの意見も聞きながら、どういった支援ができるか、考えていきたいと思っています。","voiceIndex":49,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後ですが、やはり弱者といいますか、どうしても手助けしなければいけないというところ、それは区だけの問題ではなくて、周りの地域の支援も必要かと思うのですが、その辺も十分加味しながら、慎重に進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"そういった現状を踏まえたときに、シビックテック、テクノロジーと区民をつなげる、テクノロジーを若い世代に繋げるという部分で、これはなかなか難しいかなと思うのですけれども、区として、なかなか町会と触れ合わない方にこのシビックテックを周知する方法というかやり方というか、何かお考えはあるのでしょうか。","respondent":"山本情報推進課長","answer":"いずれにしましても、デジタルデバイドの解決策というところでは、なかなか町会の方が主体となってシビックテックの力を使うというのは難しいとは思いますが、例えばそのほか、ＮＰＯ団体等、区内で様々活動している団体がありますので。","voiceIndex":52,"id":"exchange-021"},{"speaker":"湯澤委員","kind":"質問・要望","question":"いざ私たちも、例えば議会報告会とかそういったものをして、より多くの方から意見をもらおうとしても、どうしても人数があまり集まらないとか、もしくは偏った年代とか、そういった方の意見しか聞けないというところもありますので、こういったものはすごく大切だと思うのですけれども、そういったところでやはり民間の方とかは、役所の情報とか品川区の情報がより多く情報公開されていれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういうときに、先ほどのＮＰＯ団体とかもそうですし、観光協会とか様々な団体があるので、そういう観光面でやっていくのもいいのかなと思っているのですけれども、その辺はどういうふうにお考えになっているのかということと、五反田バレーの人たちもどういう考え方で、例えばイベントを双向性にしていったらいいのではないかとか、そういう意見もあったと思うのですけれども、分かる範囲でいいのですが。","respondent":"山本情報推進課長","answer":"１点目のシビックテックの観光面での活用ということで、今、区の事業としては、オープンデータのところを１つ側面にして連携を図っているところですが、シビックテックの活用事例というところでほかの自治体を見ますと、オープンデータに限らないで。","voiceIndex":56,"id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。特に五反田バレーの人たちというのは、すごく若い、いろいろな発想があると思うのです。そういうところの意見も取り入れながら、また観光面でもこれから活用方法をいろいろ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"１１月２０日にリニューアルされるということですけれども、具体的に夜中の１２時前後に切り替わるのか、もちろん真っ昼間ということはないとは思うのだけれども、その辺について、補足で説明していただけますか。","respondent":"大澤広報広聴課長","answer":"朝の８時半から９時の間に新しいページに切り替わります。","voiceIndex":63,"id":"exchange-025"}]},{"id":"topic-05","title":"では次に、(2)水辺のライトアップ整備工事（アイル橋）請負契約","agenda":"では次に、(2)水辺のライトアップ整備工事（アイル橋）請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"今回、３社が最初に名のり出て、２社が辞退ということで、「辞退理由：３」のほうは、積算してみたら予定価格を超過してしまったということで、やむを得ない、事業者としてもそういう判断だったと思うのですけれども、時々ありますが、配置予定技術者の配置ができなくなったためという理由は、割とよく辞退理由に出てくる気もするのですが、今こういう状況の中で、技術者の取り合いではないですけれども。","respondent":"東野経理課長","answer":"応募いただいた３社につきましては、これらの配置について、申込み時点では配置が可能だったと思われます。ただ、ほかにもいろいろ工事の受注とか、そういった段階で、専任の監理技術者の配置ができなくなったということはありますので、そういったことが原因と思われます。","voiceIndex":69,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"詳しくないのですが、企業の中でそういう技術者がいらっしゃるのだけれども、その企業の中で幾つか工事が重なってしまって、そういう人を必要とする工事を同時期にはできないということで、そういう判断をされたという理解でよろしいでしょうか。","respondent":"東野経理課長","answer":"監理技術者も様々いらっしゃるのですけれども、専任のとなりますと、その工事の期間は縛られるようなことになりますので、ほかの工事と重なった場合につきましては配置ができないというようなことも考えられます。","voiceIndex":71,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日、建設委員会でも報告があるということなので、一言、意見だけ述べさせていただきたいのですけれども、以前にもどこかで述べたと思うのですが、品川区で水辺のライトアップ事業を、この間、各地でやってきていまして、私のところにも、率直にきれいだという声と、幾らかかっているかを知ると、そんなにかかっているのという、どちらが多いとは言いませんけれども、両方の声を伺うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"私も聞きたいのですが、水辺のライトアップ整備工事（アイル橋）ですけれども、この工事では何か特殊技術が必要なのでしょうか。その辺、もし分かれば教えてください。","respondent":"東野経理課長","answer":"そうしますと、大体Ａクラスの業者というのが３９社おりますので、特にこれといって特殊な技術が必要というところではないものです。","voiceIndex":75,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"今、課長が言われましたけれども、電気工事士の資格があればできるというような工事だと思うのですが、今現在、地域のこういう電気設備業もそうですが、建設業というのは、仕事がなくなっていると私は聞いています。ところが、３社だけで、それぞれ事情があるのだと、それもよく聞きますけれども、特段特殊技術が必要のないこういう工事に、何で品川区ではもっと多くの業者が入札に参加できないのですか。","respondent":"東野経理課長","answer":"その中でも３社応募いただいたということで、入札としては十分成り立っている案件だと考えております。","voiceIndex":77,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区は、支払いもいいし、きちんといろいろな事業を毎年こういうふうに予算立てして、区内事業者に発注して、受注していただいているわけですよね。それが、これぐらいの規模で専任の技術者がいないとか手当できないとか、先ほど申し上げましたが、忙しいときなら分かります。今回、制限付き一般競争入札ですよね。やはりここは何か改善していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"},{"speaker":"新妻副委員長","kind":"質問","question":"よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-032"},{"speaker":"須貝委員","kind":"意見","question":"今回の令和２年職員の給与に関する報告及び勧告の概要ですが、課長もご存じのように、今、新聞とかテレビで、賞与の話、ボーナス、１２月分の情報が出ていますけれども、ゼロ回答や半分になっているところもある。様々な情報が我々の耳に入ってきています。それが特別区人事委員会で精査して民間事業所を調査したら、民間と公務員の特別給の差は０.０５か月しかないと。","respondent":"黒田人事課長","answer":"今回の特別給、いわゆるボーナスの調査については、国の人事院と東京都２３区の特別区人事委員会が共同で調査していまして、今回の調査対象が、令和元年８月から令和２年１月までの支給月数と、令和２年２月から７月までの月数を調査して。","voiceIndex":84,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"月例給は８月１７日から９月３０日まで実施していると。消費税も上がっているし、それから冬は温暖化もあったし、米中の関税の貿易戦争もあったし、そういうことを考えると、区民が肌で感じる感覚と特別区人事委員会の感覚とはあまりにも離れ過ぎていると思うのですが、もう一度、同じ答弁になるのかと思うのですが、これでいいのでしょうかと思うので、ご見解をお聞かせください。","respondent":"黒田人事課長","answer":"現在の情勢と少し乖離があるのではないかというご指摘かと思いますが、いわゆる給与勧告につきましては、国家公務員の勧告と併せて、特別区の調査を特別区人事委員会で行っている中では、調査方法としては、こちらの資料に記載があるとおり、企業規模５０人以上で、かつ。","voiceIndex":86,"id":"exchange-034"},{"speaker":"湯澤委員","kind":"質問","question":"そういった職員の方々に、今回、民間の減額というのを鑑みて、役所のほうも減額されるということなのですけれども、ぜひ職員の方々がご納得できるようなきちんとした説明をされたほうがいいのではないかなと思いますが、その辺に関してはいかがでしょうか。","respondent":"黒田人事課長","answer":"職員でありますので、我々の給与については法律に基づいて支給されているというところは、まず一義的に認識しなければならないというところでありますので、そういった意味では、情勢適応の原則、民間準拠というところで。","voiceIndex":88,"id":"exchange-035"},{"speaker":"湯澤委員","kind":"意見","question":"品川区の職員の皆さん、本当にこのコロナ禍においても頑張っていただいていると思うので、これからもしっかりと頑張れるような、気持ちの上でも、気を落とす、そういったことがないようにしていただければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"調査数は１,１０７民間事業所ということなのですが、これは区内でいうと、パーセントといいますか、どれぐらいに当たるのですか。要するに、一般的なところの調査なのかということを把握したいと思って伺うのですけれども、いかがでしょうか。","respondent":"黒田人事課長","answer":"今回、特別区人事委員会の調査方法が、特別区内の企業規模ということで調査しておりますので、品川区内とダイレクトということではないのですけれども、調査の規模としますと、特別区人事委員会の資料によれば、対象事業所が９,８６９事業所ありまして。","voiceIndex":91,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほども課長が、ご自分のというよりも、要はルールがこういうふうになっているわけですから、今は仕方がないことなのだと思いますけれども、何か今後のことで、例えば庁内でこういうことについての議論があれば教えていただきたいと思うのですが、いかがでしょうか。","respondent":"黒田人事課長","answer":"庁内での議論ですが、特別区人事委員会の給与勧告も、いわゆる２３区全体のということで、いろいろ地域的な状況も違う中では、ダイレクトにその区の状況を反映しているかと言われれば、それはなかなか、制度上、そうでない部分もあるのかもしれませんけれども、私どもとしては。","voiceIndex":93,"id":"exchange-038"},{"speaker":"吉田委員","kind":"意見","question":"最後のほうは私の感想ですけれども、以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2182#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29229,"voices":98}},{"id":"r02-20201110-14","meetingId":"r02-cm11","date":"2020年11月10日","dateIso":"2020-11-10","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"前回の説明より３年間延びたというようなことなのですけれども、それで、本当は私などは要望どおり、公的な目的で本格活用していただきたいということで、そういう立場で質問したいのですが、まず、これは３つのものに使うことになっているのですけれども、この７,６３３m2あるのですが、この３つのもので。","respondent":"佐藤企画調整課長","answer":"健康センターも５００m2程度で、園庭とか自転車置き場等々も整備しますので、その辺で５,０００m2弱は施設として使うというところで、ご案内のとおり、こちらの敷地、形がちょっと正方形ではないので、その辺も含めまして、５,０００m2弱を今のところ使う予定です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、この暫定活用している間は敷地をほぼぎりぎり使って、それ以外にはもう使いようがないという形で使っている感じになるのですね。もし余っているようなら、ほかに何かに使えるのではないかと。であるならば、例えば公園であったり、もう少し使いようがあるのではないかとお尋ねしようと思ったのですけれども、念のためその点はいかがでしょうか。","respondent":"佐藤企画調整課長","answer":"今後地元のほうも入ってきますので、例えば防災面で何か必要であるとか、地域の集まりに使うとかいう場合には、若干の広さは提供できるかなという程度の間は余裕を取っているというところですが、本格的に何かまた新しいものを建てるというのはちょっと厳しいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それは、荏原複合施設は令和８年度までで、それから保育園２つに関しては令和１０年度までですけれども、だから２年間のずれがあるのですが、その残り２年間に関しても同様な感じなのですか。","respondent":"佐藤企画調整課長","answer":"委員ご指摘のとおり２年間ずれがあるというところもありますので、そちらに関しましては今後本格活用を検討する中で、例えばその後、荏原複合施設が戻った後の敷地を利用して何かを建てるとかいうことも考えていきたいとは考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"意見","question":"そうしますと、これらの３つの施設がなくなった後に本格活用ということになるのだと思うのですけれども、まず本格活用をお考えなのか。それから、その本格活用ということになると、その中身についてどういうことをお考えなのか。それをお願いいたします。","respondent":"佐藤企画調整課長","answer":"当然暫定施設ですので、それが本来の目的を達してそれぞれの施設に戻った場合は、本格活用は当然区として検討して、本格活用するです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"その本格活用の中身についてどういうことをお考えなのでしょうか。","respondent":"佐藤企画調整課長","answer":"本格活用の中身なのですけれども、大変申し訳ないのですが、まだ時間があるというのと、それまでの間に様々な行政需要ももしかしたら変わる可能性もありますので、今後またじっくりとたたき台等を検討していきたいと考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"その本格活用について今後考えるということなのですが、それではいつ頃からどういう形で考えていくということなのでしょうか。いつ頃から検討を始められる予定なのでしょうか。","respondent":"佐藤企画調整課長","answer":"本日この時点でいつ頃かというのは特にまだ決まっていないところではありますけれども、当然期間が決まっていますので、それまでに間に合わせるように適切なタイミングで検討し、また議会に報告していきたいと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"例えば、先ほど保育園、特養ホーム、公園などが非常に有力な候補として地元のアンケートからは上がっているのだということを申し上げましたけれども、例えば特養ホームの建設ということになりましたならば、例えばの話ですけれども、どのぐらい前から検討が必要なのでしょうか。","respondent":"佐藤企画調整課長","answer":"特養ホームの整備に関して検討が必要な期間というご質問だと思うのですけれども、公設で建てるなり、民間を誘致するなり、それなりに一定の検討と調整の必要があると思いますので、一概にここで例えば５年です、６年ですというのは言えませんけれども、何度も言ってあれですが。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"保育園だけを取ってもかなりまだまだ建替えだったりとか、かなりの築年数が経過しているものがあると思うのですけれども、そういう区有施設、これは１０年近く前だと思うのですが、品川区公共施設有効活用プランというのが出されたときに、区有施設の築年数が全部書かれた一覧表も資料で出てきているのですけれども、これを見ると築年数がかなり経過したものがいっぱいあるわけですが。","respondent":"佐藤企画調整課長","answer":"ご質問を２点いただいたと思います。１点目の本日ご報告している暫定活用の次についてということですけれども、今現在暫定で使って、もう一回暫定というは考えておりませんので、必然的に本格的になるのだろうと今現在は考えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで、今、鈴木ひろ子委員からもお話がありましたが、もしこの近くでほかの施設等もありましたら、やはりそういうところに関しても移転先というのが品川区ではなかなか見つからないと思いますので、ぜひそういうところはご検討してくださいまして、この活用する期間が今のところ定まっているように感じますけれども、逆に延長してでも、そういう場所があったら有効に使っていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の時点でのこういう計画がされているものの一覧表みたいなものはあるのでしょうか。そうは言ってもまだなかなか土地がないので、そのようにできていませんということですけれども、では、どういうふうにしてその建替えを区として考えられているのか、今後の見通しというか方向性についても改めて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"２点目といたしまして、建替えの方向性なのですけれども、こちらに関しましては先ほどご答弁したとおり、用地がないと進まないというところもありますから、例えば大きめの公園についてどういった活用ができるのかというところは、日常的に検討はしているところではありますが。","voiceIndex":22,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"今回、公有地の活用ということで、旧第一日野小学校跡地の説明をいただいたのですが、６月の行財政改革特別委員会で出されていたのが４件あって、それで活用方法がまだ決まっていないもので、旧東品川清掃作業所があるかと思うのですが、今の検討状況などがどうなっているのかということをご説明いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6098#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":6739,"voices":29}},{"id":"r02-20201111-18","meetingId":"r02-cm11","date":"2020年11月11日","dateIso":"2020-11-11","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部副委員長","kind":"提案","question":"議会運営委員会にて決定した備考と呼んでいる調査事項の細節に則し、廃プラ・ＣＯ２削減、集団回収を含む品川区としての環境・リサイクルに関する取り組み、さらに、みんなのメダルプロジェクトなど、東京２０２０大会に関連した事業について理事者よりご説明をいただき、委員の皆様にはそれに対するご意見や積極的なご提案をいただいて、活発な議論をしていきたいと考えております。","respondent":"辻オリンピック・パラリンピック準備課長、提坂環境課長、工藤品川区清掃事務所長","answer":"私からは、東京２０２０大会における持続可能性の取り組みについてご説明申し上げます。Ａ３の資料をご覧くださいませ。環境課では、地球温暖化防止ですとか、良好な地域環境実現のための様々な取り組みを行っているところですが。１番目のメダルプロジェクトの経緯ですが、区では小型家電リサイクル法が施行された平成２５年度より、区施設にて月２回拠点回収を実施しております。","voiceIndex":2,"id":"exchange-001"},{"speaker":"渡部副委員長","kind":"提案","question":"それぞれありがとうございました。説明が終わりました。質疑に入ります前に、委員の皆様に申し上げます。今期の委員会では、委員・理事者間の質疑応答にとどまらず、委員の皆様同士での活発な討議を中心にして進めていきたいと考えております。ぜひ積極的にご意見・ご提案等をいただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"これが１つ目です。それと、環境の取り組みについてというところですが、マイボトル促進ということで、ペットボトルを削減していくという意味ではとてもいいと思います。今示されているような庁内ですとかあるいは区民への啓発の努力、これは大切なのですけれども、これだけでは抜本的なペットボトル削減は達成できないと思うのですけれども、そこら辺についてのお考えはいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長、提坂環境課長","answer":"東京２０２０大会に対する区として、オリンピック・パラリンピック準備課としての取り組みです。例えば物品を発注する際はリサイクル製品を優先して使うですとか、そういった区のエコリンクに沿ったものはまずやっております。ペットボトルの抜本的な削減ということで、なかなか抜本的な削減ということは非常に難しい問題ですけれども、これも地道な啓発活動が大切だと思いますので、広報ですとか、あとＥＣＯフェスティバルですとか区民まつり。","voiceIndex":7,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり目標達成が大事なわけですから、ごみを削減していく、地域環境を守っていくということが大事なわけですから、その観点から、大事なことであればやはり言うべきことは言っていただきたいと思います。続けて環境学習交流施設なのですが、展示計画の２番目のところがどういう内容なのかちょっと分かりづらいので、「時間軸で」と書いてありますけれども、内容を少し知りたいので伺わせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡部副委員長","kind":"質問","question":"安藤委員、環境学習交流施設なのですが、詳細については総務委員会、建設委員会等でその契約ですとか委託ですとかいう話になりますので、今回はあくまでもこの環境の取り組みという中でのご質問に対してお答えするということでよろしいでしょうか。その範囲で答弁をお願いいたします。","respondent":"提坂環境課長","answer":"来年度検討してまいりますというのは、事前にそれぞれの地区からご相談いただいて、どういうものを使いたいかということを踏まえた上で、これは予算編成段階なのでちょっとどうなるかは分かりませんけれども、それに対して実際に購入していただいたものについて。","voiceIndex":11,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただその内容ですけれども、やはり重要な点が２つ私はあると思うのです。伺いたいのは、この温暖化の展示内容の検討にあたっては、政府の方針の範疇でということで忖度することなく、何よりも科学的知見を大事にして、欧州を含めた世界の動向ですとか、市民社会の見解も含めて視野を広く持って展示内容を考えていく必要があるのではないかと思うのですけれども、それはいかがでしょうか。","respondent":"提坂環境課長","answer":"今、委員ご指摘のとおり、政府の方針どおりやっているだけではなかなか解決できないということで、そういう一面も確かにあると思いますが、この環境学習交流施設がオープンした後に、中にはいろいろなコミュニティラウンジですとか。","voiceIndex":13,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、集団回収ですけれども、参加団体は増えているが回収量が減っているということです。そして、９割を占める新聞、雑誌、段ボールと。それと、本事業をやっているのですけれども、今後の方向性についての区のお考えを伺いたいのですが、この事業目的として、「地球環境を守る資源循環型社会をめざす」と書いているのですが、この目標というのはどこに置いているのか、伺いたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"回収量の関係です。今、私もご説明しましたとおり、新聞・雑誌の減少というのが総回収量減の主な原因です。その要因といたしましては、これはペーパーレス社会ということで、やはり新聞を取る方が少なくなっている、雑誌等を買う方が少なくなっていると。","voiceIndex":15,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"順次お伺いをしていきます。みんなのメダルプロジェクトに関連しまして、品川区は希少金属の有効活用のため小型家電を回収しているということで、そして平成２９年度、平成３０年度の回収分をメダルプロジェクトに提供したということなのですけれども、メダルではなくて、通常はこれはどのように小型家電を回収して、その後の有効活用につなげているのか。具体的にどうされているか、お聞きします。","respondent":"工藤品川区清掃事務所長","answer":"それで、その認定事業者が選別等を行いまして、一定の中間処理を行いまして、最終的に精錬事業者といいまして、それからいろいろと希少金属を取り出すような事業者があります。そちらのほうに行っているです。","voiceIndex":17,"id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。では、その後はその民間の事業者に行って、あまりにも活用方法が多岐にわたるので、区としてはそこまで細かく追えないということでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"実際、区としてこのようなものになったというところにはなかなかならないわけなのですけれども、私どもが確実にそういった形で認定事業者のほうに渡しておりますので、そういった中で有用な貴金属として、様々な製品等の部品に供給されているです。","voiceIndex":19,"id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"何かそのあたりの分析というのはされているのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"段ボールの増の理由です。今委員からお話がございましたように、私どもも同様に考えてございまして、やはりインターネット通信販売の影響といった中で、本当に今かなりの量が出ているような状況です。","voiceIndex":21,"id":"exchange-010"},{"speaker":"筒井委員","kind":"質問・要望","question":"折りたたむにしても、折りたたんだ後、かなり分厚くなってしまうので、今後オリジナルエコバッグのようなものを作られるのかどうか分かりませんが、今、ナイロン地で折りたたむと相当薄くなる、ヒット商品ランキングでも入りました、具体的な名前を出すと「シュパット」というものがありまして、ですから、どうせ今後作られるのでしたら。","respondent":"提坂環境課長","answer":"なかなかいい商品を作ってもらったとか、あと逆に今、委員ご指摘のとおり、もう少しコンパクトなものがいいとか、いろいろ様々なご意見もありますので、その辺のご意見を踏まえながら、来年度以降どうするかということをまた検討してまいりたいと考えています。","voiceIndex":23,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"こうしたレジ袋有料化時代に合わせて、次回はコンパクトに持ち運びできるようなものにしていただきたいと思いますので、ぜひご検討のほどよろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"環境の取り組みのところでまず伺いたいと思います。そして、４のしながわＥＣＯフェスティバルなのですけれども、今年は感染症拡大のために中止になりました。来年度のこの中止の判断というのは、感染症が今また広がってきている中で、どのように判断されるのかというところを伺いたいと思います。","respondent":"提坂環境課長","answer":"しながわＥＣＯフェスティバルの来年度の開催についてですけれども、当然予算の要求もさせていただいて、基本は開催という方向で考えてありますけれども、今も第三波が来たとかという報道も流れてありますけれども。","voiceIndex":26,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"啓発紙芝居のほうなのですけれども、多分小さい子向けに分かりやすいものというのは理解はするのですけれども、例えば家庭の中での食品ロスをなくしていく方法の話なのか、それともまたお買い物だったりとか、どういった内容なのかというところを知りたかったので、もし分かれば教えていただきたいと思います。そして、ＥＣＯフェスティバルです。そこのところをお伺いいたします。","respondent":"提坂環境課長、工藤品川区清掃事務所長","answer":"紙芝居の詳細な内容については、申し訳ございません、ちょっと把握していませんけれども、とにかく小さな園児の皆さんが分かりやすいように、食べ物を大切にしようとか物を大切にしよう、それが地球がいつまでも元気でいられるとか。給水スポットの件ですけれども、イベント会場でのモデル的な実施を見まして、今後展開できるかどうかということを検討してまいりたいと思ってあります。","voiceIndex":28,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどもほかの委員の質疑であったのですけれども、環境への興味・関心につながる体感型展示については、要望も入るのですけれども、日頃の、一人ひとりの生活がその環境問題につながっていくといったことを、参加された方、来られた方が考えられるようなところだといいと思うのですけれども、そういったイメージをちょっとお知らせいただければと思います。","respondent":"提坂環境課長","answer":"今、委員がおっしゃったとおり、一人ひとりの日々の生活、それがまさに時間軸ということで、１秒、１日、１年、１０年、そういう中でどういうことをしているかということを皆様に改めて実感していただいた上で、その一つひとつの行動が。","voiceIndex":31,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"各地域のお店が出店して、そのイベントの中で販売をするというところもあって、それぞれのお店の容器が使われているケースもあって、プラスチックを使っているお店もありますので、それを環境にいいものに変えていくのもなかなか難しいところもあると思うのですが、品川区で行うイベントの中においては。","respondent":"提坂環境課長","answer":"確かにそういう問題もあるので、その辺、ちょっとまだ数字的にどの程度かということは把握してございませんけれども、その辺も課題の一つとして捉えてありますので、今後検討してまいりたいと考えております。","voiceIndex":33,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"この東京スマイルボトルキャンペーンは１１月２３日までの期限つきではありますけれども、オリンピックに向けて給水所ができたりとか、そういうことも東京都は引き続きやっていくのではないかと思われるのですが、ここら辺との連動ですとか、地図の中では品川区の給水スポットがここですよということも出されておりますので、そこともぜひ連動しながら取り組みを進めていただきたいと思いますが。","respondent":"提坂環境課長","answer":"品川区でどういう給水スポットがあるかということをもう少し分かりやすい形にできればということも検討してまいりたいと考えています。","voiceIndex":35,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都のこの給水スポットはキティちゃんとコラボをしていて、非常に分かりやすく出ておりますので、品川区もこういう取り組みをする中では、皆様に分かりやすく、また品川区のキャラクターにシナモロールがいますので、そういうところともコラボできるのかどうかということも含めて、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-018"},{"speaker":"つる委員","kind":"確認","question":"環境の取り組みについての３のところですが、まず基本的なところの確認で、品川区だけではないと思うのですが、２３区だと思うのですけれども、ごみの袋というのは半透明か透明であれば出していいということですか。そもそも基本のところを教えてください。","respondent":"工藤品川区清掃事務所長","answer":"ごみ袋につきましては、透明もしくは半透明ということでお願いしています。この理由といたしましては、職員が作業をする際に、ある程度一定の内容物が分かるという部分、危険性とか安全面を考慮してそのような形でお願いしています。","voiceIndex":38,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"そうすると、先ほど新妻委員からもあった、買い物をしたとき、スーパーのレジ袋、コンビニのレジ袋というのは普通にごみ袋として活用できるという理解でいますし、また昔の広報しながわを見ると品川区が推奨していた黄色いごみ袋、これは今存在としてあるのかどうかとか、どこかで購入できるのか、手に入るところはあるのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"こちらにつきましては、リサイクルショップ「リボン」で販売されている、あと西友で販売されていると聞いておりますけれども、実際、現時点でどういった形で販売しているかというのは、申し訳ございませんがちょっと不明です。","voiceIndex":40,"id":"exchange-020"},{"speaker":"つる委員","kind":"提案","question":"だから、エコバッグ、マイバッグの推進と並行して、やはり地域での環境という視点で見たときに、ごみ対策としてのそういうごみ袋の在り方というかレジ袋の在り方というか、私も実験した結果がどういう検証結果になるのか、そこまで追い切れていないのですけれども、先ほどのカラス対策の袋ではないですが、２３区で品川区だけ切り取ってやるということもまた違うのかもしれないのですけれども。","respondent":"工藤品川区清掃事務所長","answer":"いずれにしましても、その辺の排出状況等を見ながら、今後どういった形で出していただければごみ減量につながるのかとか、環境に寄与できるものなのかというところも今後考えてまいりたいと考えています。","voiceIndex":42,"id":"exchange-021"},{"speaker":"つる委員","kind":"提案","question":"ごみの捨て方が削減につながっていない。オリジナルエコバッグはざっくり１万個くらいでしょうか。ただ、来年の５月の開催にあたってはあたりをつけていかないといけないタイミング、デッドラインがあると思うので、この場で改めて提案も含めてちょっと確認したいのですが、その確認と、あと、そもそもこのＥＣＯフェスティバルをやるに際しての環境負荷はどの程度あるのでしょうか、教えてください。","respondent":"提坂環境課長","answer":"実行委員会は年明けくらいに始まるか思いますので、その中で提案等をさせていただいて、それに乗ってくれる団体があるのかどうか、そういうことでちょっと検討してまいりたいと考えています。","voiceIndex":44,"id":"exchange-022"},{"speaker":"つる委員","kind":"提案","question":"最後のＥＣＯフェスティバルのことについては、開催すること自体でどれだけ環境負荷になっているのか。それからエシカルファッションショーについては、ぜひいろいろな提案も含めて、区のほうからもやっていただきたいと思います。飲み口型水飲栓というのですか。しかしボトルディスペンサー型水飲栓というのは多分１か所もないようなのです。もしなければ、ぜひ設置してもらいたいという意味です。","respondent":"提坂環境課長","answer":"東京都のその設備については、まだ今の時点では区から要望は出してございませんけれども、先ほどの企業からの提供と設置数といった点を踏まえた上で、必要に応じて要望を出していきたいとは考えてあります。","voiceIndex":46,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほどキャラクターの話もありました。エコバッグもあります。水についてもエコだよという、そういうきっかけ作りは、やはり東京都のほうでもクイズに答えると抽選でマイボトルを差し上げますと。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、品川区の商店街の飲食店、もしかしたらその商店街の人たちは全店で“もったいない”プロジェクトを手掛けているのだみたいな形で盛り上がりが出るのかなと思っているのですけれども、品川区としてそういう区商店街連合会にお願いをするとか、そういうことはもうやっていただけているのでしょうか。","respondent":"提坂環境課長","answer":"今まで加盟していただいた１５２店舗の皆様についても今までやってきたのですけれども、個別に商店街のほうにご相談して、このお店が入っていただけそうだとか、入っていただけそうだという情報をつかんでいなくても、個別に職員が回ってご協力いただけないかということで。","voiceIndex":49,"id":"exchange-025"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはりそこで増やすのであれば、行政のほうから区商店街連合会なりに協力を依頼しまして、こういうポスターを掲げていただけると“もったいない”推進店として選ばれるので、ぜひご協力をお願いできますかとか、そういう形にするともっともっと盛り上がりが見えるのではないかと思っていますので、そこら辺を要望します。","respondent":"提坂環境課長","answer":"近々、とあるコンビニのほうにも区にお越しいただいて、食品ロスだけではなくいろいろなお話をしたいということも聞いていますので、その中でいろいろな考え方を伺って、区としてどういう形で連携ができるかということを模索してまいりたいと考えています。","voiceIndex":51,"id":"exchange-026"},{"speaker":"渡部副委員長","kind":"質問","question":"よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"視覚障害の方たちは音とかですごく楽しむこともできて、例えばお神輿とかにも臨場感を感じて、「あ、今のお神輿すごくよかったね」とかそういったこともあるので、ちょっと言い方は悪いかもしれないですけれども、このチラシの感じだと、ブラインドサッカーにだけについているのに何だか違和感を感じてしまって、何かそういう趣旨があるのかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-028"},{"speaker":"渡部副委員長","kind":"意見","question":"特にないようですので、以上でその他を終了します。なお、次回１２月４日の委員会では、特定事件調査項目のうち、レガシー政策に関することで、品川区内開催競技であるホッケーおよびビーチバレーボールのレガシーの創出について、調査・議論を行う予定であります。去る９月２８日の委員会では、ビーチバレーボールの競技会場である都立潮風公園へ視察に出かけました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":32202,"voices":63}},{"id":"r02-20201113-10","meetingId":"r02-cm11","date":"2020年11月13日","dateIso":"2020-11-13","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会報告会等準備会議および広報会議からの報告事項","agenda":"議会報告会等準備会議および広報会議からの報告事項","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"議会報告会等準備会議より、第４回議会報告会の概要について御報告します。お手元の資料No.２に沿ってご報告いたしますので、ご覧ください。」です。続きまして、２、オンライン会議（ＺＯＯＭ会議）についてです。次に連絡用の氏名・住所・電話番号の記入を求めるものです。これは、万が一感染者が出た場合に濃厚接触者を確認する、こうしたものでこのように記入を参加者に求めていくものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"意見","question":"令和２年１０月２３日に第１７回広報会議を行いまして、その中で検討した項目、区議会だより発行時のＬＩＮＥ通知について報告します。区議会だよりへの区民の方からの関心をより喚起するという目的で、１１月下旬発行予定の区議会だより、第３回定例会号について、発行時に品川区公式ＬＩＮＥを通じて通知を送信していきたいということであります。広報会議からの報告は以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"本多委員","kind":"質問","question":"立会小学校の３年生、非常に全員が矢継ぎ早に質問をしてきて、積極的な子どもたちだなとすごく感じました。やはりその場で見たものやすぐに感じたことなど、これ何、これ何、あといろいろなことを尋ねられて、子どもたちもすごい一生のいい思い出になったと思いますし、受ける我々も刺激的でよかったなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"同じです。勉強してきているなということが非常に分かりましたし、質問者も皆、まず端的にまとめて質問して、我々答えるほうが少し厳しいかなということがありました。できれば、先生方でもいいのですが、スナップ写真か何かでも撮ってあげればよかったのではないかなということは、少し感じたところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"立会小学校３年生の児童にとって、とてもいい機会になったのではないかなと思います。こうした取組は今後も様々な機会を捉えて子どもたちと接する、もっといったら、鋭い質問に我々もどう対応するかも含めて、とてもいい機会になったのではないかなと思っています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"非常に積極的な質問が飛びまして、議会にとっても、子どもたちにとっても、非常に貴重な機会になったと思いますし、忙しいというか、大変過密なカリキュラムの中で、そうした時間をつくって積極的に取り組んだ立会小学校にはすごく、敬意と言うと言い過ぎですけれども、ありがたかったなと思います。戸越小学校については……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"後ですか。分かりました。ぜひ続けて、向こうからの提案があれば、ぜひ続けていってほしいなという機会になりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-007"},{"speaker":"大倉委員","kind":"意見","question":"特に小学３年生というところで、よく議会用語なども使ってしまったり、その辺の対応をもう少し分かりやすくしてあげられたらいいなと思ったのと、それと併せて、議会の動画があったと思うのですけれども、あれは子どもが見ても分からないなというところで、子ども向けのようなものを作れたら、もっと分かりやすくていいのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私は初日の１回目から３コマやらせていただきました。４５分間の中で質疑応答の時間は大体３５分間ぐらいあったのです。これ、あっという間に時間は過ぎたのですけれども、先生からすると全員に、児童たちに質問させたいという思いは分かるのですが、もし次回は、何か事前に通告したほうがいいのかななどと。１つだけ。何かそこ、改善の余地があるのかななどと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"皆さんと大体同じ形です。小学校３年生、積極的に質問をされていたなと。印象的だったのが、議会事務局長になるためにはどうしたらいいですかという質問がたしかあったかなと思うと、すごく議会とはどのようなところなのだろうと興味がある感じなのだなと思って。こういった小学生を受け入れる議会との関係が、これからもつくれたらいいかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"ちょうど高橋伸明委員と一緒だったので、高橋伸明委員がもうその前に２回やられていたので、いろいろ事前に情報をいただいたりして非常によかったのですけれども、あと議会事務局に始まる前に、今までどのような質問があったのですかということを聞き取っておいてよかったなと。なぜ被選挙権は２５歳以上でないと立候補できないのですかと、やはり少し考えてしまうのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"何しろ質問が鋭かったことと、質問量が多かったということにびっくりしました。その中身もそうですが、これは相当先生、ならびに保護者の方からのいろいろなアドバイスも受けながら、ここまで勉強されてきたのかなと思って感心しました。ただ、どうしても議場ですから、対峙するわけです。議員と子どもたちが。でも、非常に子どもたち、よく勉強していました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"若林副委員長","kind":"質問","question":"大倉委員と高橋伸明委員と３人で対応させていただいて、高橋伸明委員が今おっしゃった、せっかく授業で来ていらっしゃるので、きちんと受け答えを、なかなか難しい質問、答えのないような質問もありましたので、そういう意味でもしっかり勉強していただく、私たちも勉強するという意味で、できれば何かこう、代表的な質問は事前にいただいて、しっかり私たちも下調べをして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5382#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":11805,"voices":41}},{"id":"r02-20201125-10","meetingId":"r02-cm11","date":"2020年11月25日","dateIso":"2020-11-25","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":6085,"voices":23}},{"id":"r02-20201130-6","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"区民委員会","time":"午前１０時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６４号議案、品川区手数料条例の一部を改正する条例","agenda":"第６４号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"コンビニ交付で戸籍の部分まで取得できるということで、コンビニ交付、品川区に本籍のある方ということでいうと、対象がどれぐらいになるのか分かりますか。さらに、今までのコンビニ交付の実績は分かるでしょうか。そこをお知らせください。","respondent":"木村戸籍住民課長","answer":"４年前からスタートいたしましたけれども、当初は２％程度だったのですけれども、徐々に上がって、今、８％というような形になっておるところです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"改正理由のところに「個人番号カードの普及を図るため」というふうにあるのですけれども、この間、１０万円の給付とか、区独自の応援給付金等々ある中で増えてきたという部分はあると思うのですけれども、これから戸籍がコンビニ交付で取得できるようになるに当たっての普及の伸び率はどのように考えられているでしょうか。","respondent":"木村戸籍住民課長","answer":"実際には普及も目的で１００円を減額してスタートするということなのですけれども、このことによって、例えば１０万円であるとか、ああいう形の伸びはないだろうというところではありますけれども、便利になるということで、実際に普及率の向上にはつながるものと考えております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"確かにぐっと伸びるものではないと思うのですけれども、そもそもマイナンバーの普及がそこまで伸びないという大本の理由もあると思うのですけれども、この間の委員会等々で伺ったときには、交付率２０％という感じだったのですけれども、今もその程度で変わりはないか伺いたいと思います。","respondent":"木村戸籍住民課長","answer":"現在も大きな変化はございません。今、２１％ちょっとだと思います。","voiceIndex":10,"id":"exchange-003"},{"speaker":"つる副委員長","kind":"質問","question":"今回また窓口交付に対してそれぞれ１００円減額されるということと、それからあと、交付の時間ですが、これ、当初、一番最初に入れていただいたときからこの時間帯なのかという認識でいるのですけれども、全体経費として、窓口でやられる人件費ですとか、その他もろもろにかかる諸経費と、今回、イニシャルでかかるいろいろなものの経費の中で、どのぐらいたつと。","respondent":"木村戸籍住民課長","answer":"こちらが業務時間外であると、今、難しいというところで、午前８時半から１７時というところで設定をしてスタートするということなのですけれども、おっしゃるように、やはり今の住民票とかとの時間の違いであるとか、利便性みたいな部分も考えますと、課題ではありますので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"つる副委員長","kind":"質問・要望","question":"経費のほうは、行政のサービスなので利益追求ではないのですが、ただ、経費の部分でどうだったかは非常に大事な視点なのかというところ、これはどこかのタイミングで、こうした区民委員会になるのか、違う場所になるのかあれですけれども、一度というか、これまでもそういうまとめられているものがあるのであれば、そうした確認はぜひしたいと思うので、その機会にぜひ出していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対です。理由も述べさせていただきたいのですが、前回の委員会でも出ましたけれども、私たちはマイナンバー制度に反対をしていまして、それで、やはり安全性等々確保できていない、そして広げれば広げるほど情報漏洩のリスクが高まると思いますし、その安全性を確保されていない中でのこうした広げるということは、やはり立ち止まって見直すべきだというふうに思っていますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"}]},{"id":"topic-02","title":"第６５号議案、品川区立創業支援施設条例の一部を改正する条例","agenda":"第６５号議案、品川区立創業支援施設条例の一部を改正する条例","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"倉庫から工房という、主にその３つのコンセプトがあると思うのですけれども、まず１点目の1)、2)、3)の部分、これはパッと見、かなり奇抜なレイアウトというか、なかなか図面を見ただけでは脳内にイメージが沸かない部分がありまして、例えばトライアルウォールというものに関しても、検索をしても何も出てこないので、果たしてこれがどういったものなのか分からないのです。","respondent":"遠藤商業・ものづくり課長","answer":"ほかのところでこういう１つの場所に複数の店舗の方がやるというケースが、ほかでも調べたところあったようなので、うちのほうの考えとしても非常に合うというところで、図では確かに分かりづらい部分があるのですけれども、そういうところで今回。","voiceIndex":28,"id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"これ、1)、2)、3)のところは、それぞれ後ろに商品が並んでいたりとかして、前に机があって、きちんとそれぞれ店員という形で人がいらっしゃるというイメージなのですか。人が店員としているだけではなく、事務所機能等もつけるには、さすがに狭いような気がするのですけれども、そういった事務所機能と店員の配置についてはどういったイメージなのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"お金の管理とかもきちんと、この裏側になるのですけれども、そういう部分も、変な話、最低限といいますか、あとは、ここは４階なども交流サロンがありますので、そういう部分をうまく活用していただいて、店員さんなど、それぞれもちろんいていただいても結構ですけれども。","voiceIndex":30,"id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"これ、今まで４万８,０００円という月額だった部分があると思うのですけれども、これは１０１号室から１０３号室までの３部屋に関して、実際に経営をしてみて、４万８,０００円の家賃だと、なかなか定着が難しいであったりとか、もしくは、逆におっしゃっている形で、４万８,０００円だとリーズナブルで、十分定着してしまうという部分だったのかどうかというのを、もう１点だけ伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"４万８,０００円という金額自体は、世間の相場からすると大分安いというのがやはりあったのですけれども、逆に言うと、長くいてしまうということで、こちらはやっぱり多くの方に使っていただきたいといいますか、そこでずっとお店を。","voiceIndex":32,"id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"今回それが１万円と３,０００円という形で、誰でも気軽に入れるようなスペースになると思うのですけれども、こちらの審査に関して伺います。","respondent":"遠藤商業・ものづくり課長","answer":"期限を決めて申込などをさせていただいて、全て面接によって、今も面接なのですけれども、その方の創業支援をしていくのだけれども、意気込みだとか、そういう部分、あとは、実際に売るものがどういうものかという部分で、では、ここで試すのがいいのか、あるいは。","voiceIndex":34,"id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"次の交流スペースの部分なのですけれども、こちらは５階に第１、第２、第３と貸会議室がありまして、こちらのスペースを交流スペースという形で使うのであれば、十分この機能を果たせるのではないかというふうに思ったのですけれども、この貸会議室を使わずに交流スペースにしなければならない理由は何かあるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回、交流サロンという形で設けさせていただいたところですけれども、武蔵小山創業支援センターの課題となっていた１つが、施設としての認知不足みたいなところがありまして、武蔵小山の駅をおりてから、パルムのほうに流れたりするところがあるのですけれども。","voiceIndex":36,"id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"こちらのスペースは、４階にある交流サロンとは、何かこれ、前も別の案件であったような気がするのですけれども、交流サロンという部分と、１階の交流スペースという部分は、これは使い分けというか、切り分けはどういった意味合いで変えていくのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"そこに中小企業診断士が常に控えているような形になりますので、もっと事務の部分、自分が創業をしていく中で、何かその辺で悩んでいる部分について、すぐにご相談ができるというような形を考えておりますので、１階のほうは、どちらかというと、外に開かれているような形で。","voiceIndex":38,"id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"こちらの工房は、シンプルに工房は、もちろん３Ｄプリンタとかが使えたりとか、専門の器具が入っているような工房だというイメージなのですけれども、こちらの工房に関して、ここに説明がある形では、チラシとか商品ポップ等の製作を行うための道具をそろえている、この道具であるとか、導入される機器がどのような機器が導入されて、ご自身で作る形が整えられるのかというふうなことを伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"ＳＨＩＰにも工房を設置させていただいて、あちらのほうは、先ほどおっしゃった３Ｄプリンタとか、そういういろいろなものが、製造業の方にお使いいただくと考えているところですが、こちらのほうは、どちらかというと、物品販売の方が多いというところで。","voiceIndex":40,"id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"小規模で店舗を新たにチャレンジとして構える方々が、業者に発注せずにここで作れるというのは、非常にいいサービスができるのかというふうに感じました。もう１点、既存商店の方も利用できるということで、こちらは結局、申込をすれば誰でも使える、誰でも使えてしまうところという意味合いでよろしいのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"既存の方に、なかなか創業支援施設が地域と交わる点もなかったのかというところもありますので、できるだけ多くの方に使っていただければというところで、今回こういった外の方も使っていただこうというふうに考えているところです。","voiceIndex":42,"id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"今回、トータルでのコンセプトが今おっしゃった形で地域の方々にどういったことがこの中で行われているかということが、視認性という部分を含めて、地域との交流性をもう少し高めるという部分が１つのポイントなのだということが、ご説明の中で１つ見えてきた部分ではあります。今、これはもう工事中ということでよろしいのでしょうか。最後にその点だけ伺います。","respondent":"遠藤商業・ものづくり課長","answer":"今年度に入って、コロナで遅くはなってしまったのですけれども、期間に間に合うように、今、工事をしています。","voiceIndex":44,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"今、工房のところで、新旧対照表を読ませていただいているのですけれども、第６条で使用の申請の話が書いてあるかと思うのですが、１項で、工房に限って申し上げると、工房を使用しようとする者は、規則で定めるところにより区長に申請して、２項で、区長から承認を受けるという、区長と言っても事実上は事務的にやられるのだと思うのですけれども、これだけ見ると素直に読めるのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"地域といいますのは、商店を営んでいるというぐらいにうちのほうでは考えているところです。","voiceIndex":46,"id":"exchange-016"},{"speaker":"松本委員","kind":"意見","question":"そうすると、１号のほうは「創業居室の使用の承認を受けていること」ということで、ここは創業居室だけでいいから、そうすると、ほかの例えば会議室とか交流スペースを使っているような人も、この１号で見るのではなくて、全部２号のほうで考えて、この２号のほうに当てはまるから、全部結局、６条の承認を受けないといけない、最終的には全員承認を受けないといけないというふうな条文の見方でいいのか。","respondent":"遠藤商業・ものづくり課長","answer":"何らかの形で、当然、貸出しするときには承認行為が必要になりますので、どこかの要件に該当するということでの判断をするような形になるかと思います。","voiceIndex":48,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"分かりました。ちょっと細かくてすみませんでした。工房ということで、レイアウトを見ると、どういうふうに申請するのかというところで、１階なので、入ろうと思えば簡単に入れるところだと思うのです。実際に１階の部分に誰かセンター側の受付の人がいるのか、あるいは、ほかの階に行って申請するのか、その辺りはどういうふうになっているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、当然、係員のものが１階、チャレンジショップなどもありますので、そういうところにちょこちょこ行ったり来たりという形になろうかと思いますので、無断で使っていればといいますか、分かるのかなというふうには思っているところです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"今のところで、正に無断で使っている場合が一応あり得るのかというところで、できるだけ広く使っていただくというコンセプトと、例えば、ここは目黒区との境目なので、全然区民と関係ない目黒区の方が、ある意味、使ってしまうというのも、それも品川区との関係ではどうなのかというところはあると思うのですけれども、その辺りは完全にセキュリティというか、ちゃんときっちりと管理できるかと言ったら。","respondent":"遠藤商業・ものづくり課長","answer":"こういうところの建物としてセキュリティが大事だというのもある一方で、ある程度、創業支援といいますか、そういう交流が大事だというところで、なかなかそこら辺のバランスは難しいところかと思います。","voiceIndex":52,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論をお伺いしますけれども、１億円、東京都から半分おりてくるというものを使うわけで、そもそも１０年が経過し施設の老朽化というのはあるのですけれども、１０年で老朽化してしまうのですかということが１点。ということは、また１０年後に１億円以上かけて改修するのですかということと、あと、２番もよく分からない。品川区だけではないです。その辺についてお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"費用対効果というところのお話で、どうしても区の自治体ですと、そのまま法人税がダイレクトに区のほうに入ってくるというわけではないので、そういう部分では、なかなか数字でという部分では難しいところはあるのですけれども、今言いました。","voiceIndex":54,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"各創業支援施設は特徴を持っていただきたいと思うのですけれども、その辺の場所も大崎というか五反田にあり、武蔵小山にあり、天王洲にあり、駅は西大井ですけれども、大井にありという形で、品川区が創業者に対してというふうになるのであるならば、今やっている最中ですけれども、そういう意味で伺ったので、もう１回その辺の答弁をいただきたいのと、それと。","respondent":"遠藤商業・ものづくり課長","answer":"創業支援としての効果です。すみません、投資という部分だけではなくだと思いますけれども、こういう形で自治体が創業支援をやっているというところは、ほかの地域、２３区でも品川区は突出していると考えています。","voiceIndex":56,"id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいのが、交流スペースをつくることで、先ほどのお話の中で人の流れがとか、認知度が低いといったところで、交流スペースをつくって、今も外装をという、分かるようにというお話があったのですけれども、それはどういう情報、データに基づいてというか、何かアンケートをとったりとかということがあって、根拠があってそういうふうにしているのだと思うのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"１階の広さについて、交流サロンを設けたり、いろいろと細かくさせていただいたところではあるのですけれども、何分スペースにどうしても限りがある中で、どういう形が一番いいだろうというところで、今回、工房にしたり、あるいはショップを少なく小さくしてみたりとか。","voiceIndex":58,"id":"exchange-022"},{"speaker":"大倉委員","kind":"質問","question":"例えば、よく言われるのは、ここでお祭りとかを開催して、いろいろな人、地域の人に見てもらうとかというのも１つ形としてはあるのかというところでは、今もそういった取組とかをされてきているのかと思うのですけれども、その辺の状況とかが分かれば教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"今まで武蔵小山創業支援センターもいろいろと外に向けてのアプローチなどをさせていただいているところはあるのですけれども、なかなか入るときにエレベーターで４階まで上がっていただかないとなかなか分かりづらい、そこまで行かないと、１階は店舗でしたので。","voiceIndex":60,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません、１点だけ。先ほど、質疑の中でアンケート等は行っていないけれども声を伺ってということだったのですが、そうすると、改修等に向けて、アンケートや調査的なことはしてこなかったということでいいですか。","respondent":"遠藤商業・ものづくり課長","answer":"通常の使用の部分といいますか、特に改修に向けてのアンケートは特にとったというふうには聞いておりません。","voiceIndex":62,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、そういうところでこういう声があったとか、今までの利用者の方からの声が多々あったみたいなことがあると、なるほどというふうに、改修の必要性があったのかなということが分かると思うのですけれども、これだけだと、しかも１億円もかけているので、本当かなというか、そうなのかなという思いはすごくあるので、ぜひそういった声等も載せていただけたらと思いますし。","respondent":"遠藤商業・ものづくり課長","answer":"武蔵小山創業支援センターが、先ほど言った視認性が悪いだとか、中身が今っぽくないといいますか、そういう部分についてはいろいろなところから御意見は頂戴しているところでございました。","voiceIndex":64,"id":"exchange-025"},{"speaker":"つる副委員長","kind":"質問","question":"一番最後の別表の中には、店舗のところを４万８,０００円から１万円の記載しかないのですけれども、そのトライアルウォールについての３,０００円というのは、規則の中に３,０００円という記載があるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"おっしゃるとおりです。ここだけ３,０００円を規則のほうで定めさせていただいているところです。","voiceIndex":66,"id":"exchange-026"},{"speaker":"つる副委員長","kind":"意見","question":"ここについては無料で利用可、用途とか趣旨が、また路面に面しているというところで全然違うのでしょうけれども、その辺の金額を無料にした考え方とか、あとは、どういう形で、今空いているという状況、飛び込みなのか、その上で予約できてしまうのか、その辺りを。","respondent":"遠藤商業・ものづくり課長","answer":"１階の今度できる交流サロンと、４階の交流スペースというところがありまして、名前については愛称なども考えているところで、同じような名前なので、趣旨がちょっと違うところがあるので分かりづらいというふうに思っているところです。","voiceIndex":68,"id":"exchange-027"},{"speaker":"つる副委員長","kind":"確認","question":"現在、改修中というところなのですが、２・３階に保育園が入っていますね。そういう形で区の施設としてやる中で、そういう換気スペースだとかについても、ちゃんと設備として、今回せっかくやるのだから、そういったものがついているのかということがちょっと気になったので、その辺りについて確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"保育園が２階と３階に入っておりますけれども、当然こちらで大きな音が出るときがあるということで、説明に行きまして、時間など、お子さんが寝る時間だとかも配慮して、既に大きい音の出る部分は終わっておりまして、そこの部分について、特に保育園から。","voiceIndex":70,"id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"換気については、当然そういう当初の中からきちんと盛り込んだ部分があるのだと思いますし、現在言われているところのそうした設備は、当然、しつらえとしてあるべきものなのかという理解、なければ、当然追加でやってもいいぐらいのものは私は思いますし、これだけ３店舗分としてスペースがあるわけですから、特に人がそれなりにいらっしゃるのだろうなという想定をすると。","respondent":"遠藤商業・ものづくり課長","answer":"今いろいろと御意見を頂戴した部分も含めて、多くの方が武蔵小山創業支援センターがあそこにあるという認知の部分、ちょっと見てみようかなという部分も含めて、いろいろとあそこの盛り上げのために考えていきたいというふうに思っております。","voiceIndex":72,"id":"exchange-029"}]},{"id":"topic-03","title":"に記載の順番を入れ替えまして、(5)第６３号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"に記載の順番を入れ替えまして、(5)第６３号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"前回の販路拡大は、たしか７月１日から約２か月間行われたと思いますが、私も地域の商店の方からも、この助成の件でいろいろ相談を受けたりしました。そこで、幾つか質問させていただきたいのですけれども、助成対象の事業者数が４７０件ということで、これは具体的に飲食店と企業とかだと思うのですけれども、ざっと大まかに教えていただけますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"対象となったところで一番多かったのがサービス業で１５０件弱でした。２番目に多かったのが飲食業の方で、こちらが１４０件弱ぐらい。はぐっと下がりまして、製造業、小売業、医療業など病院が大体３０件から５０件ぐらいというような形になっているところです。","voiceIndex":87,"id":"exchange-030"},{"speaker":"小芝委員","kind":"質問","question":"９月末にたしか審査が完了されて、その決定通知書を送られたということなのですけれども、振込はこれからということでよろしいのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"買ったものがその金額より安かったとか、そういう部分があろうかと思いますので、実績報告をいただきまして、その審査をまたさせていただきまして、要するに、最初の申請と間違いないということであれば、その段階での振込となりますので。","voiceIndex":89,"id":"exchange-031"},{"speaker":"小芝委員","kind":"質問","question":"それと、不交付、交付されていない事業者が４３件ということで、これも主な理由を教えていただけますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"不交付になった団体が１０％弱いらっしゃるのですけれども、書類審査になりますけれども、今回の感染症の対策という部分からはそういうふうに読み取れないというのが大きなところです。","voiceIndex":91,"id":"exchange-032"},{"speaker":"小芝委員","kind":"質問・要望","question":"第二弾ということで、これから冬場を迎えるというところで、区のほうで冬場に特化した感染防止対策のイメージがあれば教えていただきたいと思うのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"冬場となりますと、１つは乾燥する部分と、それからなかなか窓を開けづらいという部分があろうかと思いますので、今回、空気清浄機とかも含まれておりますので、例えばエアコンなどをつけるのに、そこに例えば空気の循環の機能がついているような場合ですと、今回。","voiceIndex":93,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"対象者ですけれども、なぜ「ただし、販路拡大支援助成の交付決定者」は除いてしまったのですか。","respondent":"遠藤商業・ものづくり課長","answer":"あるいは、先ほど何名か、１０％の方が落ちてしまっておりますので、その方につきましては引き続き対象としておりますので、そういう部分をまず救っていくという言い方は変ですけれども、そういう方にご利用いただきたいという部分で。","voiceIndex":95,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問・要望","question":"これ、特別助成金ではないですか。新規のそういうものが出てくるわけですよね。本当にサービス業、飲食店の方たち、大変ですから、ここを手厚くしていっていただきたいという思いもありますので、その辺について、上限２０万円で１回だけではという思いがあるのです。３回でも４回でも、コロナという意味の環境において、やっていっていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今後も、これと同じものになるか、あるいはまた別の形になるかは分かりませんけれども、私ども、支援するのは一番大事な仕事だと思っているところですので、今年度あるいは来年度に向けて、いろいろな形で、この助成も含めていろいろ考えていきたいというふうに思っております。","voiceIndex":97,"id":"exchange-035"},{"speaker":"くにば委員","kind":"質問・要望","question":"これ、最終的に募集期間の間、これが６,０００万円という上限ではなく８,３００万円が実際の交付決定額、３００件に対して最終的に４７０件の助成対象になったという形で、こちらに関しては最終的にこの形のこの金額、この申請件数、これが当初予定していたよりも圧倒的に多く追加でやっていただきたいという希望があって、こちらを追加で行ったという認識でよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"前回の販路拡大支援助成で３００件で予算要求させていただいたのですが、ご好評いただいたというところで、多くの方にご申請いただいて、だからといって予算の範囲内でそこで切ってしまうのかというところが、それもどうかという、こういうご時世なので。","voiceIndex":99,"id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"今回さらに追加で５００件、これが年明けの３月１５日までの経費対象期間、募集期間が２月２６日までということなのですけれども、私も先ほど藤原委員が言ったことと同じ意見なのですけれども、例えば、これは実際、一度前回までの４７０件に入った方でも、今回、例えば先ほどおっしゃっていた冬場なので、空気清浄機を入れたほうが、そういったウイルスが蔓延しないような乾燥対策になりますとなると。","respondent":"遠藤商業・ものづくり課長","answer":"一方で、例えばこういう販路拡大助成ではないのですけれども、ほかの例えば東京都なり国なりということで、感染症対策の助成金などもありますので、なかなか採択が厳しいというような話も聞いているところですが、そういうものを紹介しながら、あとは第三弾になるか。","voiceIndex":101,"id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"もう１点、取組例の部分ですけれども、こちらが空気清浄機の導入というのが追加されたのと同様に、前回、取組例は様々範囲が広いので、販路拡大支援助成という枠組みでコロナ対策という部分に関して、いろいろな機器であるとか、こういった例えばＥＣサイトの構築、外国語版ウェブサイトの導入というすごく幅広い部分まで対象になっていると思うのですけれども、実際にこちらの取組例の。","respondent":"遠藤商業・ものづくり課長","answer":"今回のこちらの助成は、できるだけ広く使って、いろいろなもので販路拡大につながるのだということが判断できれば、基本的に認めるというスタンスで、それが９０％の採択率という形になったと思います。","voiceIndex":103,"id":"exchange-038"},{"speaker":"くにば委員","kind":"質問・要望","question":"大変驚きました。今おっしゃった中で、では、第一弾のときに新しくウェブサイトを立ち上げました。これはウェブサイトを立ち上げるのはもちろんいいことなのですけれども、それに対して上限２０万円の助成をして、いざそれが効果がどの程度あったのかどうかというようなご意見をどれぐらい聞いていらっしゃって、それがさらにフィードバックできるのかということを伺いたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの今回の助成ですけれども、正直、第１回目はいろいろと助成させていただいて、いろいろとそれぞれの企業が運用されているところなのですけれども、正直、まだ検証が十分にできていない中で、今回、第２回目をさせていただいたところがありますので、今後。","voiceIndex":105,"id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"ちょっとこれ、逆説的な意味合いになるのですけれども、では、これは４７０件お申し込みいただいて認可した事業の中で、ウェブサイトの構築等が一番申込が多かったということは、それ以外に、あまり対象がなかった、アクリル板等の導入が１０％ぐらいしかなかったということですけれども、これはむしろウェブサイトの導入にこれが使えますという例示がなかったら。","respondent":"遠藤商業・ものづくり課長","answer":"全てのいろいろな業種があって、それぞれの中でこういうものを設けたとかという部分があるかと思いますので、今の中ですと、そこが整理できていないところがあるので、そういう部分につきましては、恐らくうちのほうで経営相談をさせていただいているので。","voiceIndex":107,"id":"exchange-040"},{"speaker":"くにば委員","kind":"質問・要望","question":"総括として、結局、前回３００件の当初の補正予算の件数、これが今回は１億円の予算で５００件ということで、さらに力を入れてどんどん、前回のように知らなかったであるとか、間に合わなかったということがないように、もっとアピールをして宣伝をしていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"この予算のところで、今、審議はしていますけれども、ホームページのほうでは募集の案内とかが始まっているというように見ていて思うのですけれども、その中で、申請の対象として出てきているので、助成対象者ということで、法人事業税と法人都民税を滞納していないことと、これは当然入っていらっしゃるのですけれども、新型コロナの関係で猶予されている方たちも一定数いらっしゃると思うのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"あくまでも滞納されているという形ですので、その辺の手続といいますか、猶予の申請をとっていただければ、そこはこちらの助成の対象とさせていただければというふうに思います。","voiceIndex":110,"id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"これもほかの補助金とか助成金でもよく問題になりますけれども、これは最終的には課税対象というか、お金が入っている分は、この２０万円については課税対象ということでよろしいのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"特にこれが非課税対象というふうにはなっていないので、基本的にはそのように考えております。","voiceIndex":112,"id":"exchange-043"},{"speaker":"松本委員","kind":"質問","question":"これ、パソコンだったらワードでもいいのですけれども、タブレットで見ていただくと、多分ずれているのがかなり分かっていただけるのではないかと思うので、ここは早めにＰＤＦに差し替えていただいて、ずれがないような形にしていただければと思いますが、ここのところはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ご指摘いただいたとおりだと考えています。すぐにＰＤＦに直したいというふうに思います。","voiceIndex":114,"id":"exchange-044"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば、その中で２０万円満額使われていない方たちへの、例えば前回１０万円で、今回また出て１０万円というような上限まで使えるような検討はされたのかどうかということを教えていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"満額に満たなかった方をどうするのだですけれども、検討はさせていただきましたが、今回につきましては対象外という形で決めさせていただいたところです。","voiceIndex":116,"id":"exchange-045"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうすると、前回も１０万円申請した方は、今回新たに申請しても、申請はできないということであるということで、そうすると、先ほどの話の中でも新たに冬場の対応策で空気清浄機も含めてオーケーですよというお話の中で、空気清浄機は今もちょっと見たら、物によっては４万円とかで買えたりするようなものとかもあったり、いいものだと１０万円かかってきてしまいますが、そういうものを買って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これだけ今この委員会の中でもそういった方たちも対象にすべきだという声が出ていますので、もう１回検討していただくということはできないのでしょうかということを伺いたいのと、あと、私たち共産党としては、マスクやアルコールも対象にしてほしいということを決算委員会でも要望したのですけれども、消耗品だから駄目という、対象外ですという答弁だったのですが、やっぱりコロナ。","respondent":"遠藤商業・ものづくり課長","answer":"マスクにつきましても、お店の方がずっと使っているということも認識していますし、逆に言うと、お店にいらっしゃる方もみんなマスクをしているような状況ですので、店舗だからマスクをするとかというのではなくて、普通の方もやられている部分があるので。","voiceIndex":119,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱり販路拡大なので、どんどん来ていただきたいし、入ってきていただきたいという状況をつくるための助成金なので、そのためには、マスクだったりアルコールは必ず必要になってくるものなので、そこを引き続き、まだまだ感染症がおさまらない状況ですので、引き続き検討していただきたいと強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-048"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そういう意味では、大きく品川区も品川区の店舗等に支援の力を入れていただいているというメッセージが非常に伝わるのですが、よりそういったところがきちんと伝わるように、感染症対策をちゃんととれるのだというところが伝わるようにしてもらいたいということと、あとは使い切れていない、先ほど大倉委員の言った部分のところは、今後、藤原委員も、あと二弾、三弾と可能性としてはあるわけですから。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは特にスピード感を重視というところがあったものですので、口頭ではご相談があれば区内事業者と相談することはできるかと、何社かという形にはなろうかと思いますけれども、一応配慮はしていきたいと考えていますが。","voiceIndex":122,"id":"exchange-049"},{"speaker":"つる副委員長","kind":"質問","question":"そこは自由競争ではないですか。区内事業者だろうと、他区の事業者だろうと、お金幾らですか、区のお金だから、やっぱりそのようにかけ過ぎてもあれですよねという、そういうバイアスがかかると思います。そこはうまくしっかりと、いい意味で区内が潤うようにやっていければいいのではないかと思いますので、今後の周知の方法とかで検討いただければと思います。時間がないのにすみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-050"}]},{"id":"topic-04","title":"議案審査、(3)第７３号議案、指定管理者の指定","agenda":"議案審査、(3)第７３号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"この選定委員の有識者２名というのは、どういう方なのか教えていただきたいのと、あと、現指定管理者に継続してもらうということなのですけれども、そのための選定委員会が開かれて、どのようなチェックがされているのかということがちょっと分からないのですけれども、公募などをする場合は、何社か来ると、点数で一番高いところというふうになると思うのですけれども、こういう継続してもらうときは。","respondent":"古巻文化観光課長","answer":"項目等につきましては、そちらに条件を、基準を書かせていただきましたけれども、それをより具体化したような内容で、例えば利用者の平等な利用およびサービスの向上を図るものという中には、具体的かつ効果的な点があるかとか、突発的なケースに対応できるような体制があるか。","voiceIndex":139,"id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"継続していただくので、それなりの信頼だったり実績があるというのは分かるのですけれども、もし何か問題が起きたときに、こちらもこの議案に対して賛否を問われているので、そういった部分では責任があるなと思っているので、そこの部分は知りませんでしたということでは議会としての説明が果たせないと思うので、そうした資料をぜひ公開していただきたい、公表していただきたいと思いますし。","respondent":"古巻文化観光課長","answer":"選定委員会ですけれども、今回につきましては、この日、１日だけ、１回だけの選定委員会ということでやっております。","voiceIndex":141,"id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今のお話だと、減るであろうという部分を区が上乗せして委託料を出すということでいいということですか。お願いします。","respondent":"古巻文化観光課長","answer":"必要な分については区として指定管理をしっかりしていただける金額を出すという、そういう考え方ですので、場合によってはそういったことも起こり得るというふうに思います。","voiceIndex":143,"id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それと、指定管理者のところで、代表者が、理事長が中川原さんということで、元副区長だったのだなと、ちょっと私、知らなくて、そうかと思ったのですけれども、元部長とか、元課長、管理職の方が、ここの品川区立総合区民会館においては、何人ぐらいいらっしゃるのか伺いたいのですが。","respondent":"古巻文化観光課長","answer":"区のＯＢとして元管理職の方、中川原理事長を入れまして３名の方が在職されております。ご承知と思いますけれども、現職の派遣で２名、管理職が行っておりますので、合わせると３名プラス２名ということで５名ということになるのだというふうに数えることもできるかと思います。","voiceIndex":145,"id":"exchange-054"},{"speaker":"松本委員","kind":"質問","question":"今日は、議案というところでお伺いしたいと思うのが、こちらの文化振興事業団の評議員会が先だって開かれて、そこでちょっとほかの議員から聞いたところだと、こちらの総合区民会館で、本来は施設を貸し出すときに営利活動はしてはいけないというふうになっていたところ、どうもそういうことがあったというふうな話を耳にしたのですけれども、この辺りのご事情についてご説明いただければと思います。","respondent":"古巻文化観光課長","answer":"当然、ルールに違反をしたというような、もしくは疑わしい利用は厳に避けるべきというふうに考えますので、しっかりその辺は今後チェックをしていく、要は、そう見えるようなことすらもいけないといいますか、ルール違反になりますので。","voiceIndex":148,"id":"exchange-055"},{"speaker":"松本委員","kind":"質問","question":"今回のことを伺っていると、区民の方からの情報提供だったと思うのです。それに当たって、指定管理者制度の場合は、行政と管理の指定をされている側で２つあるわけですけれども、先ほど、厳しくチェックしていくというお話でしたけれども、一義的な責任の主体は指定管理者にあるのか、区側にあるのか、そこの点をお願いいたします。","respondent":"古巻文化観光課長","answer":"ただ、現場での管理という面でいうと、指定管理をする側にもある程度チェックをお願いせざるを得ないところがありますので、それをしっかりさせるという意味では、区立の会館でありますし、区側がしっかりそこはチェックさせるというような。","voiceIndex":150,"id":"exchange-056"},{"speaker":"松本委員","kind":"質問","question":"例えば、申請の段階で、先ほどちょっと隠すみたいな話がありましたけれども、隠しておいて、実際には中ではやっている、でも、中で何をやっているのかというのを、では、どうやって把握していくのかとか、本件についても少し伺っているのは、その場ではなかったかもしれないけれども、事後的にそれを誘導していくような流れがあったみたいな。","respondent":"古巻文化観光課長","answer":"具体的にというところでは、お話しできる具体策はないのですけれども、今現在、検討中であるということで認識をしています。","voiceIndex":152,"id":"exchange-057"},{"speaker":"松本委員","kind":"質問・要望","question":"質疑というか、要望という形になると思いますけれども、今回はどうしても公募ではなくて、一旦流れてしまいながら決まっていく。これ自体はコロナの問題もあるので、やむを得ないところはあると思うのですけれども、やっぱりどうしても管理監督の部分がおざなりになる可能性は十分にありますので、そこの部分は今も申し上げたとおりで、具体的なところで把握していただくように努めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-058"},{"speaker":"藤原委員","kind":"確認","question":"そもそも論をお伺いしますが、今回こういういろいろな事情があって、指定管理の公募をしなかったのですよね。これは品川区の指定管理者という意味の条例というか、ルールにおいて、条例とかがちゃんと担保してあるのですね。つまり、文章として特別な事情がある場合は、公募せずにみたいなことは入っているのか、まず確認。","respondent":"古巻文化観光課長","answer":"今回公募によらなかったことについては、基本的には公募であるというような原則がありますけれども、やはり事情によっては特定の事業者を選定できる、そういったような形のルールになっておりますので、そこは何か特別な扱いをしたということではないです。","voiceIndex":155,"id":"exchange-059"},{"speaker":"藤原委員","kind":"質問・要望","question":"これ、課長、はっきり言っておきますけれども、特別な配慮をしたのでしょうという意味で質問したのではないですよ。したのではないですからね。何の意図もないですからね。そういうルール、担保になっているのですねという話で伺っていますので。ただ、課長、１つ不安になったのは、今回はこういう事情で公募をしませんでした。言いたいことを分かっていただけますか。だけど、独立した団体ですよね。","respondent":"古巻文化観光課長、山崎文化スポーツ振興部長","answer":"ですから、文化振興事業団が手を挙げてくれなくなったときはというのは、なかなか想定が難しい部分があるのですけれども。要は、ホール収入がないということですから。そういう中で受けていただけるところはないだろうと区では見込んで、今回については、再度、指定管理者を特定する形で公募によらない方式をとらせていただいたというようなことです。","voiceIndex":157,"id":"exchange-060"},{"speaker":"藤原委員","kind":"質問・要望","question":"ずっと区の行政に関してやられていたわけですから、そういう意味において、そういう方たちが、さっきも３人行かれているというお話が出たけれども、すごくそういう意味で区との関係、また行政マンとしての経験が発揮されていくのだろうと考えていますので、何かこういう質問をしてしまうと、表に出ていないというか、オープンにしていないみたいな答弁になってしまうけれども、そうではなくて。","respondent":"古巻文化観光課長","answer":"確かに区のＯＢの方々が運営には携わっているという意味では、区側のいろいろな事情であったりとか、考え方についても、当然ご理解いただきながら事業をしていただいているというふうに認識しておりますので、そこが強みというか、文化芸術の分野、それから生涯学習の分野では。","voiceIndex":160,"id":"exchange-061"},{"speaker":"くにば委員","kind":"提案","question":"このオンライン配信というのが、そういった形のライブであるとか、コンサートであるとか、舞台演劇であるとか、そういったものをオンラインで配信をして有料のチケットを売るであるとかということを考えているのかどうかというのが１点と、もう１つ、その下の部分にある休館期間中は地域へ出向くアウトリーチ型の事業を展開するという、ここの部分に関して。","respondent":"古巻文化観光課長","answer":"舞台をオンラインで配信をするというような形で、それをさらに推し進めるというか、もう少し、今年はやむを得ずみたいな面もあったのですけれども、次年度以降につきましては、そういったオンラインの仕組みをきちんと経常的といいましょうか。","voiceIndex":162,"id":"exchange-062"},{"speaker":"くにば委員","kind":"質問","question":"オンライン配信の部分ですけれども、きゅりあんとして、オンライン配信をどんどん推し進めていくということイコール、うちの施設はオンライン配信をするだけの設備が整っていますと、インフラが整っていますという部分がきちんと担保されていないと、なかなか営業面でプラスにアピールしていけないと思うのです。先にそれを伺いたいです。","respondent":"古巻文化観光課長","answer":"ただ、そういった面では、一定程度のインフラがあるということで、まずは試み的にやってみるということが１つあるのだというふうには認識しております。","voiceIndex":164,"id":"exchange-063"},{"speaker":"くにば委員","kind":"意見","question":"こちらの中に関しては、オンライン配信は新たな事業方法、これはいわゆる公演をしたいというふうに申し出をしたお客様に対して、うちのきゅりあんはこういったオンライン配信のサービスがありますという、そのメニューの１つとして、何かきゅりあん自体が積極的にこういった新たな何かあった際には、きゅりあんがやっていくのか、それとも事業者が問合せが来たりとか、事業者に対して。","respondent":"古巻文化観光課長","answer":"提案の中では、基本的には自主事業に関わる部分でのオンライン配信というような手法の提案だったので、メインは自主事業ということだと思いますけれども、当然、設備はありますので、ご相談があった場合には。","voiceIndex":166,"id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"次の部分ですけれども、アウトリーチ型の事業、先ほど伺った形だと、何か別の場所を紹介して、そこで事業を、そこで何かイベントを行ってもらうみたいな形で、きゅりあんはどこに関わっているのかというのがちょっと見えなかったんです。","respondent":"古巻文化観光課長","answer":"文化振興事業団もそうですけれども、きゅりあんの管理運営に当たっては、区民の方々への文化芸術に触れる機会を確保するというか、しっかりと環境を整えるというようなことも１つの目的になっていますので、きゅりあん以外のホール事業だけではなくて。","voiceIndex":168,"id":"exchange-065"},{"speaker":"くにば委員","kind":"質問","question":"これは新たな取組としてということで、現状これと同等の事業はきゅりあんではしていないということでしょうか。","respondent":"古巻文化観光課長","answer":"基本は、今、指定管理という意味でいうと、きゅりあんの管理運営、それから自主事業はありますけれども、基本的にはきゅりあんを使っての様々な活動ですので、外へというような働きかけとか、実際の活動はやっていないということです。新しい試みです。","voiceIndex":170,"id":"exchange-066"},{"speaker":"くにば委員","kind":"提案","question":"ここの部分に関しては、大規模改修が終わった後も引き続き新たな事業というか、こういったこともできるのだということがプラスアルファで乗ってくると思うので、これは両輪というか、並行してぜひとも事業をもっとどんどん練り上げていって、どんどん提案をしていただいたりとか、ノウハウをためていっていただいて進めていっていただきたいと思います。以上２点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-067"},{"speaker":"つる副委員長","kind":"提案","question":"ちょっと分からない部分もあるので教えていただきたいのですが、今の質疑の中でもありまして、今回は公募せずということで、それが大規模改修もこの５年間の中である、大きな理由の１つになっているわけですけれども、当然、指定管理なので、その中で財団法人としての人件費だとか、事業収入がどれだけ見込めるのかとあると思うのですが、当然、大きく言えば管理費の中に入ると思うのですが、人件費等。","respondent":"古巻文化観光課長","answer":"それからあと、Ｏ美術館でありますとか、区民ギャラリーとか、メイプルセンターについても運営を継続しておりますので、そういった面でスタッフが大幅に減らせるかというと、それはないというふうに認識しておりますので、それから。","voiceIndex":173,"id":"exchange-068"},{"speaker":"つる副委員長","kind":"提案","question":"分かりました。だから、そういう部分では、そこに問題がなければ、ただ約１年間、あれだけ大きい施設が使えないという中では、アウトリーチだなんだと言っても、それをまかなうだけの事業展開は相当だろうなと、どういうことを考えられているのかというのは、もう既に具体的なものは何かあるのでしょうか。","respondent":"古巻文化観光課長、山崎文化スポーツ振興部長","answer":"アウトリーチだけの話をすると、まだ具体的なものはご提案はいただいていない部分はあるのですけれども、それも含めてですけれども、やはり継続的なというところをやはり重視すると。ですから、直接ホール運営にかかる委託料ですとか、直接経費については、浮かすところはしっかり浮かしながら、本体は基本的には継続しながら文化活動の支援については区と連携してやっていくというような。","voiceIndex":175,"id":"exchange-069"}]},{"id":"topic-05","title":"第７４号議案、指定管理者の指定","agenda":"第７４号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"さっきのところと同じ感じになるのですけれども、この有識者の２名は、ここの場合はどういう方になるのですか。","respondent":"中元スポーツ推進課長","answer":"２名のうち１名は弁護士の方で、もう１名は元品川区スポーツ推進委員の会長を１４年にわたってやっていらした方にお願いいたしました。やはり体育館ですので、利用者としての視点等も大事と思いまして、そういうことでお願いさせていただきました。","voiceIndex":191,"id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。ここも点数がついているのでしょうか、先ほど、文化振興事業団のきゅりあんのほうと見るところは一緒だと思うのですけれども、点数がつくというのは一緒で、何点ぐらいだったのかということを伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"配点等は当然、文化振興事業団とは違う形で、スポーツをやっている、体育館の運営という視点での配点をスポーツ推進課のほうで独自で配点等を決めさせていただいておりまして、委員１人につき１００点を持ち点としまして。","voiceIndex":193,"id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"提案","question":"港区や世田谷区などの指定管理者選定、またはモニタリング等を見てもらいますと、本当に細かく出ているのです。こちらのほうも区からの元部長だったり、元課長のＯＢがスポーツ協会のほうにはどの程度行かれているのか、伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"当初の結果につきましては、公表ということで、ホームページのほうで一定程度のものはルールに沿いまして公表します。ＯＢの在籍状況ですが、元部長が１名、事務局長です。区の管理職、課長級が１名、事務局次長ということで、こちらは区の管理職の卒業生としては２名です。","voiceIndex":195,"id":"exchange-072"},{"speaker":"くにば委員","kind":"提案","question":"２点伺いたいのですけれども、選定理由の中で、(4)番です、新規利用者の掘り起こしへの取組、ここの部分ですが、もちろんこれまでの１５年間、協会のほうでも、もちろん様々な施策であるとか、努力をして、利用者が増えるような努力をしてきたとは思うのですけれども、今回、提出された案の中で、具体的にどういった内容で新規利用者を掘り起こそうと提案があったのか、実際にこの１５年。","respondent":"中元スポーツ推進課長","answer":"本当に毎日体育館に来て卓球とかをやっていらっしゃる方もいるのですけれども、逆に、消極的な方に対して、健康維持というか、健康づくりという視点から啓発講座やお試し体験などを実施して、運動習慣のきっかけづくりを行っていきたいという提案がございました。","voiceIndex":198,"id":"exchange-073"},{"speaker":"くにば委員","kind":"質問","question":"ご答弁ありがとうあります。今後、新規利用者をこれだけ増やしていきますという具体的な数値目標を出しているかどうか、そこについて伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"競技の種目とかによっても変わってまいりますので、それを見込むというのは、実際問題なかなか難しいところがあるということで思っているところです。","voiceIndex":200,"id":"exchange-074"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう１点が、この東京２０２０大会において練習会場として使用されることによる収支変動を見込んでいること、ここの部分ですが、結果的に１年、後倒しになった部分についても見込んでいたのかどうか、私のほうでは、もしかしたら中止もあり得るのではないかというふうには、様々な部分を見ていて思うことではあるのですけれども、ここは中止の可能性はきちんと見込みをつけているのかどうか伺いたいです。","respondent":"中元スポーツ推進課長","answer":"それともう１点のほうの中止の可能性ですが、もし練習会場として使われなければ、そこももちろん見込んでおりまして、使われなければ、逆に区民の方に利用していただきますので、それほど大きな、特殊清掃が必要だと言われている競技でございましたので。","voiceIndex":202,"id":"exchange-075"},{"speaker":"くにば委員","kind":"質問・要望","question":"コロナ感染症の拡大に関してもそうですけれども、オリンピックの延期もここに関しては、例えば１年前には全く想像がつかなかったことだと思います。ですので、そういった何かあったときの緊急的な部分で運営はなかなか難しくなるという部分もきちんと、現状、スポーツ協会がそこもバッファとして乗り越えるだけの力があったということに関しては、私は非常に評価をしております。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":63318,"voices":219}},{"id":"r02-20201130-7","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"厚生委員会","time":"午前１０時００分～午後 ４時０７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６７号議案、地方税法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","agenda":"第６７号議案、地方税法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"国民健康保険は、高過ぎるということが根本の問題として私はあると思っているのですが、結果として延滞金を支払った人というのは、国民健康保険を払いたくても払えない人が払っているのではないかという懸念があるのですが、そのような方が延滞金を払う羽目になっているのではないかと思っているのですけれども、どのような人が延滞金を徴収されているのか、その辺。","respondent":"池田国保医療年金課長","answer":"今年４月に延滞金を取らせていただくような形になりまして、実際には６月の賦課額から徴収されるような方が多くなるかと思いますけれども、現在２２件の納付がございまして、延滞金の金額としましては１０万８,８００円ほど。延滞金の利率についてですけれども、特例割合を使っておりますので、納付期限の翌日から３か月を経過するまでにつきましては年２.６％、納付期限の翌日から３か月を経過した日以降につきましては。","voiceIndex":7,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"１番目のほうですが、国民健康保険で取って、介護保険と後期高齢者医療で取らない理由は何かとお伺いしたのですが、その点もう一度お答え願います。研究中と答えられたのですが、現段階で国民健康保険で取って、介護保険と後期高齢者医療で取らないという運用をなさっているのは、どのような理由でそのような運用になっているのかということをお伺いしたつもりなのですけれども。","respondent":"池田国保医療年金課長、宮尾高齢者福祉課長","answer":"後期高齢者医療につきましても、現在延滞金については研究をしていると、この部分でございまして、実際２３区の中で延滞金を徴収する区では、ほとんどの区が後期高齢者医療分についても延滞金を徴収させていただいているところです。ですので、全体の第１号被保険者の方の中でも収入の低い方がこの納付書払いという形になっておりますので、ここについては慎重かつ丁寧な対応が必要かというように考えております。","voiceIndex":10,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"今、介護保険のほうの説明はあったのですけれども、国民健康保険では研究が終わったから取るようになったのだということですが、その研究で出された結論というのはどのようなことなのですか。まだ研究中という、後期高齢者医療ではまだ取らないでおこうという、その差が出たところを知りたいので、ご説明いただければと思うのですが、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"延滞金の運用につきまして、こちらはもともとの部分が公平性の、保険料の公平な負担を図るためということがまず１つございまして、国民健康保険につきましては、介護保険、後期高齢者医療と同様に特別徴収をするものもありますが。","voiceIndex":13,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"にもかかわらず、国民健康保険では延滞金を取る運用に転換して、介護保険、後期高齢者医療ではまだ転換していないというところの、取るほうの区の側から見てどうなのかという理由を、率直なところをお伺いしたかったのですけれども、今のご説明では何かもやっとして、私にはちょっと理解できないのですが、もう少しご説明いただければと思うのですけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"国民健康保険料の負担のことですけれども、国民健康保険料につきましては、収入の少ない方につきまして減額の制度もございまして、実際に国民健康保険に加入されている方のおよそ４割が減額の該当をされているところです。","voiceIndex":15,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"ですから、むしろ国民健康保険料には、そのようないろいろな問題がもともとついて回っているので、延滞金を取ってまで納めさせるということよりも、滞納しないように高過ぎるものを引き下げていくことこそ、私は課題ではないかと思うのですけれども、その点ご認識いかがでしょうか。お伺いいたします。引き下げることこそ課題だと思うのです。","respondent":"池田国保医療年金課長","answer":"ですので、私どもから保険料を上げるということではなく、一応使うべきお金のために保険料を決定するということ、それから国や都に対しては予算についてのご要望はさせていただいているです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのような点で、高齢者の方の生活というのはますます厳しい状況になっていますので、ぜひ取らないという運用を継続していただきたいと強く要望しておきたいと思います。介護保険のほうは、もともと、年金が１か月１万５,０００円以下という厳しい方が普通徴収になっている。それから延滞金の徴収はこれからでもやめるべきだということで、改めて要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"}]},{"id":"topic-02","title":"冒頭申し上げましたとおり、取上げる順番を変更し、議案審査（17）を先に行います。 それでは、第６３号議案","agenda":"冒頭申し上げましたとおり、取上げる順番を変更し、議案審査（17）を先に行います。 それでは、第６３号議案","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"すみません。一番最初に説明いただいた高齢者福祉課所管分の裏表のあるものですけれども、１番、２番、３番と３つ説明がありますが、これの１番、２番が、当初１１月６日締切の、東京都が１０分の１０を助成しますと言った制度を利用してやったもの、ＰＣＲ検査などを助成しますといったものに申し込んだものだと理解してよろしいのでしょうか。その点をお願いいたします。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長","answer":"３点目につきましては、寄附金の活用ですので、委員お尋ねの内容とは異なるものというふうに思われます。障害者福祉課につきましては、都の補助金ではなく、自治体のクラウドファンディングを活用するものとなっております。","voiceIndex":34,"id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"なぜ申し込まないのかと思っておるのですけれども、１４プラス１で１５施設ですよね。なぜこのように限定した申込みをされたのかということをお伺いしたいと思います。障害者福祉課に対しては、なぜ申し込まなかったのかというふうにお伺いしたいと思います。私としては申し込んでいただきたかったというか、申し込むべきではなかったかと思うのですけれども、そのような点、いかがでしょうか。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長","answer":"こちらにつきましては、当然各施設によって必要だと判断すれば、この補助金を利用できるという立てつけになっておりますので、こちらにつきましては制度の案内を、もちろん事業所もしっかりと情報は持っておりますが、念のためというか。委員お尋ねの申込みについてですが、グループホーム等に新たに入所される方につきましては、これまでの予算の範囲内で対応が可能と考えております。そのため、今回の申込みは見送った次第です。訂正します。","voiceIndex":37,"id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"これから申し込むこともあり得るということですか。あるいはそもそも必要とは考えていないということですか。","respondent":"松山障害者福祉課長","answer":"予算の範囲内で対応可能と考えておりますので、補正予算を提出するということを致しませんでした。","voiceIndex":40,"id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"都が１０分の１０を助成してくれるという制度ですけれども、それに申し込んで、ＰＣＲ検査や、いろいろやれるということを、通所施設やグループホームなどに関して、障害者福祉課として必要だとはお考えにならなかったというようなことなのでしょうか。","respondent":"松山障害者福祉課長","answer":"実際に必要だと考えております。ただし、現段階では新たな入所者の見込みが立てられなかったため、もし新規入所者がいましたら、予算の範囲内で対応していく予定です。","voiceIndex":44,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは高齢者、そして障害者の部分と、最後の医療のところ、健康課のところも関係してくると思うのですが、私の記憶ではしながわ活力応援給付金の、これは私ども３会派で区長に、ぜひこれを行ってほしいということで、５月に要望に行ったときにセットで、区民からの善意、いわゆるエッセンシャルワーカーの方への善意を、エッセンシャルワーカーのみならず、保育とか、医療とか、介護、高齢者、障害者。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長、高山健康課長、櫻木生活福祉課長","answer":"私からは寄附金を活用した事業について、実際にその物品に寄附金を使わせていただいたということが分かる考え方につきましてですが。私どもの所管におきましても、高齢者福祉課と同様に、寄附金を使わせていただいた、区民の善意ということが事業所にきちんと伝わるような形の。私のほうからは支援金ということで、各医療機関への支援ということで、実際のところは現金の給付という形になりますので、この現金給付の原資として。見込算出の考え方です。","voiceIndex":46,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"医師会、歯科医師会、薬剤師会、１件につき、何というのでしょう、ありがたいのですが、額としては、すごく多いということでもないですから、ただ、区民の思いなのだ、区の思いなのだというところをぜひ、押しつけがましくなっても仕方ないのですが、伝わるようにやっていただきたいということが１つです。それと生活福祉課の住拠確保給付金のほうなのですが、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで、東京都の補助には、この新規入所者だけではなくて、ショートステイの利用者やデイサービスの利用者も対象に入っていたのですが、新規入所者が外からその施設に入るということから考えると、ショートステイの利用者も、それからデイサービスの利用者も、常に外から施設に入るというところで、考え方は同じなのではないかと思うのですが、新規入所者だけに限ったというのはなぜなのか。","respondent":"宮尾高齢者福祉課長","answer":"今回のＰＣＲ検査費用の助成ということでの対象の考え方についてですけれども、まず今回はグループホーム、それから特別養護老人ホームのうち、地域密着型１施設分を予算案として提出しています。","voiceIndex":52,"id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この東京都への申請はもともと１１月９日までだったのが１週間延ばされて、１６日に締切だったわけですけれども、それに間に合う形でお知らせができたのか、お知らせができて新規入所者にやりたいという特養ホームは多いと思うのですが、実際申請されたのかどうかということは、区立の特養ホームも多いわけですから、そこのところは区として把握が必要なのではないかと思うのですが、把握されているのか。","respondent":"宮尾高齢者福祉課長","answer":"デイサービスにつきましては、補助金の申請ルートからいたしますと、区が予算化をしてということになりますけれども、こちらにつきましては、今従業員に対してやっているところですので、まずはそちらの検査をしっかりと実施させていただきたいと思っているところです。","voiceIndex":54,"id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからショートステイにしても、デイサービスにしても、必要性についてどう考えられるのかという辺りもお聞かせいただきたいのですが、今回は１６日で締切ってしまって、東京都も５０億円の予算を組んだということなのですが、その５０億円の予算のほぼちょうどそれぐらいの申込みがあったということで、申請を締切ったということを東京都からも聞いたのですけれど、そのような点でいえば。","respondent":"宮尾高齢者福祉課長","answer":"具体的には、利用者の方の検温を毎日毎日行うですとか、消毒等の徹底等に万全を期しているつもりです。ですので、今時点でこの考え方をしっかりと継続していって、引き続き感染拡大防止に万全を期してまいりたいと思っているところです。","voiceIndex":56,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"医療の現場でも、国の分で新型コロナウイルス感染症の患者に直接接する方は２０万円とか、そうでない方は１０万円とか、そのほかの医療の方にも５万円とか、品川区でも１人６万円の、さらに新型コロナウイルス感染症の患者に接する分というようなものが補正予算でも組まれましたけれども、国のほうも区のほうもまだ出ていないというようなことを、現場の看護師から言われたのですが。","respondent":"宮尾高齢者福祉課長、高山健康課長","answer":"ただ、区はこれまで５月の補正予算におきましても、支援金ということで支給させていただいたり、あるいは日頃から感染防止対策に役に立つと思われるような物資、こういったものの提供につきましても、しっかりと協力をしていますので。第３回定例会において、区独自の上乗せ分として慰労金の予算をお認めいただいておりますが、医療機関様のほうにお話を伺うと、つい先だって申請が終わったというようなお話も伺っておりまして、この後、都において審査が行われ。","voiceIndex":58,"id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その点を確認させていただきたいと思います。それから申請は、３か月に１回申請して、その後何とか頑張ってやれるというようなことで、援助しなかった人でそのまま条件に合うような状況が続いている場合、再度の申請というのはできるのでしょうか。その点、制度の仕組みなのですが、お聞かせいただけたらと思います。","respondent":"宮尾高齢者福祉課長、櫻木生活福祉課長","answer":"今回私どものほうで提出させていただいている分につきましては、予算をご承認いただいた後、速やかに各職員の下に渡るよう執行してまいりたいと考えています。４月にご申請された方が１２月で切れるということへの区の対応です。１つは、住居確保給付金の制度については、国のほうで様々議論をされているところですので、その状況を注視しつつ、適切に対応していきたいと考えております。","voiceIndex":61,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのような点でいえば、生活保護にならないためにも、この住居確保給付金の延長というのが必要なのではないかと私は思うのですけれども、一番困った状況を、実態を、具体的な状況をつかんでいる自治体から国に延長を求めていただきたいと私は思いますが、その点についてはいかがでしょうか。","respondent":"櫻木生活福祉課長、高山健康課長","answer":"住居確保給付金の延長ですが、国のほうで具体的に１２月の延長というような方向で検討されていると認識しておりますので、注視してまいりたいと思います。区がこれまで各団体と関係性を持っております区の公益事業の事業協力規模でありますとか、あるいは各団体からも個別にご支援などをいただいておりますので、そうしたものを参考に、金額については検討させていただいたといったものです。","voiceIndex":64,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この消毒液というところでは、事業所のほうからの要望ということで消毒液になったのか、また、施設で困っているものや足りないものなどということに対しては、各施設にどのような形でご意見をお聞きしているのかということについてもお聞かせいただけたらと思います。","respondent":"高山健康課長、松山障害者福祉課長","answer":"区でこれを始めるにあたって、特に他区との比較の中でこのことの検討を始めたわけではなくて、やはり今回ガバメントクラウドファンディングなどで集めていただきました医療支援という、その区民の願意に沿いたいというところから。そのニーズに合わせた形で、衛生物品等を今後も考えてまいりたいと考えています。","voiceIndex":67,"id":"exchange-019"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"安心して外出できるようになるし、そのような意味で、目黒区と品川区は接しているのですけれども、品川区に住んでいるがために希望しても受けられない、そうであるがゆえに不安をかこって生きなければいけないということで、ちょっとかわいそうになるというか、そのように思うのですが、それこそこれからでも手を挙げて導入してほしい制度だと私などは思ってしまうのですが、その点品川区。","respondent":"鷹箸保健予防課長","answer":"抗原の定性検査については、検査結果が一番早く出るものですが、こちらについては本来は症状がない人に実施してはいけないところですけれども、今検査できる医療機関が非常に増えてきた中で、抗原定性検査をやる医療機関は多いのですが。","voiceIndex":82,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区の感染状況というのを、ちょっとネットで見たのですが、２６日は２２人、２７日は１８人、２８日は１２人ということで、このところ２桁で感染者がかなり増えているという状況にあると思うのですが、そこのところではかなり逼迫した状況というか、緊迫した状況というようなことに、政府の感染症対策の分科会としても提言を出していると思うのですが、そのようなところでは。","respondent":"鷹箸保健予防課長","answer":"その中の重症者の割合ということではないのですが、どのような方々が多いかといいますと、やはり濃厚接触者の方々への検査を確実に実施するようになった結果、重症者の方も中にはいらっしゃいますが、無症状のご家族でお子さんとか。","voiceIndex":85,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"介入が遅れれば遅れるほど、その後の対応の困難さや社会経済活動への影響が甚大になるため、迅速かつ集中的な対応が求められるということで、これは本当にＧｏＴｏに対しての対応だったりとか、この検査だけでない、様々な接触を避けるというような対応が求められるというところも言われているわけですが、そのような中で、政府や自治体、さらに一般の人々や事業者も含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどもちょっと申し上げたのですが、やはり今、大変緊迫した状況になっているのではないかと思うのです。このようなところに対しては、厚生労働省も求めているし、また分科会でもこのような形で出ていますので、ぜひやっていただきたいと思うのですけれども、それに対しては区としてどう考えられるかということについてお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そのようなところでは高齢者福祉課にも、そのような実態を見て、保健所としてこう考えるというようなものは示して、そのようなものを拡大できるようにすべきではないかと私は思うのですが、そのようなものを所管課にお任せというような形でいいのでしょうかということが１つです。それともう一つは、先ほども申し上げましたけれども、新規入所者というようなことで、やはりＰＣＲ検査をやったほうがいいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それに対して保健所としてはどう考えられているのか。そのようなことを保健所として別にやったほうがいいとは思わないけれども、それは高齢者福祉課のほうで判断してやってくださいという考え方なのか、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"保健所として、新たな入所者に対してのＰＣＲ検査は意義のあることだと考えるということは、お聞きできてよかったと思います。そのようなことで考えるのであれば、ショートステイやデイサービスというのも、保健所として必要、意義のあることだというようには考えられないのでしょうか。小規模多機能とか、そのようなところに対しても同じ考え方になるのではないかと思うのですけれども、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"保健所の検査とは別に実施するようなのですが、その検査の実現可能性も含めて、今後検討していくべき問題かというように考えております。","voiceIndex":103,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"コロナ鬱になりそうだというぐらい心配をしていてもＰＣＲ検査を受けられないという状況がありますので、そのような方が本当に一度でも受けることができれば、それは１つの安心になりますし、またそこで感染が見つかれば、そこから保護、隔離というようなところに、対策にもつながっていきますので、ぜひそのようなところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-027"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。担当課より丁寧な説明をしていただきました。区は現状をしっかりと捕らまえて適切な判断をしていただいていると考えていますので、本陳情に関しましては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"意見","question":"本日結論を出すで、不採択です。理由は、前回もそうだったのですけれども、この陳情の方も１つのお考えだとは思うのですが、区からの説明がそのとおりだな、合理的だなと思いますので、不採択ということにします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-029"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。今、感染が急拡大しているのも、このＰＣＲ検査が少ないがために起きていることだと思います。ますます、今度こそ増やしていかなければならないと思います。採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いします。前回もご説明いただいたということで、今回も同じように、現状区のほうが行っている対応で十分やっていただいているということです。具体的な方策も説明いただきましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-031"}]},{"id":"topic-04","title":"したいと思います。 それでは、最初に通所系サービス施設といたしまして、(2)第７７号議案、(3)第７８号議案、(4)第７９号議案、(5)第８０号議案","agenda":"したいと思います。 それでは、最初に通所系サービス施設といたしまして、(2)第７７号議案、(3)第７８号議案、(4)第７９号議案、(5)第８０号議案","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"全体に関わることなので、お伺いしたいと思います。そして７施設について、今回から有識者を入れての選定を開始したというご説明があったのですが、有識者を入れた基準、なぜ有識者を入れるところがあって、入れないところがあるのか、そこのところを教えていただきたいのが１つです。まさか机上配付ということはないと思うのですけれども、その辺りを教えていただきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"外部委員に関するご質問ですけれども、今年度の全庁的な外部委員の導入ということにつきまして、令和２年８月１９日の総務委員会のほうで全庁的な説明があったというように聞いておりますが、企画部主導で今年から試行という形で。","voiceIndex":122,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"内部のことなのであれなのですが、今回入っていただいて、当然活発なご意見が出されたと思うのです。そのようなことであれば、なぜその文言が入っていないのかというところ、抜き書きしたからそれを省略したということなのか、ちょっとその辺りを確認させていただきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"障害者施設についても同様ですが、抜粋、（抄）ということで書いていないのですが、福祉部所管施設ということで、継続性が求められるということについては同じように対象になっております。","voiceIndex":124,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"このようなことで、細かいことですが、確認させてください。拡大をしていただきたいと、当然私としては思いがあるのですけれども、やはり今までの内部の委員だけでは、それはどうしても方向性というものが見えるものですから、その中で外部の方のお声が入ることによって、また違った方向性も見えるのかなということもあるものですから、その辺りの今後の方向性を教えてください。","respondent":"寺嶋福祉計画課長","answer":"今回は年度が始まってからこういった案内が来まして、急遽準備したということもありまして、残念ながら全施設はできなかったのですが、可能な限り拡大していく必要があろうと考えております。","voiceIndex":126,"id":"exchange-034"},{"speaker":"おくの委員","kind":"質問","question":"この「実績等を評価し」の中に利用者の満足度調査というようなものは入っているのでしょうか。その満足度調査というようなことは行っているのでしょうか。それを伺いたいと思います。それともう一つ、「引き続き指定管理者として指定することが合理的と認められる場合」と書いてありますが、この「合理的と認められる場合」というのは、具体的にどういったことなのでしょうか。それを伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"毎年モニタリングを行っている中で、利用者満足度の視点という項目があるのは前回のモニタリングのときにもご説明させていただいたと思うのですけれども、それも１つの重要な判断材料になっているです。","voiceIndex":128,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"有識者が２名ずつ入ったということですけれども、これは私もずっと前から外部委員は入れるべきだというようなことで申し上げてきたので、品川区もやっと入ることになって、今までは部課長だけでしたので、よかったなと思うのですが、この有識者の方も入った選定委員会というのは、その後のモニタリングには関わっていかないのでしょうか。この選定のときだけ関わるというような形になるのか。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"それから同様に選定委員、外部委員のお名前ですけれども、これも全庁的な取扱いが今年始まったことなので、これは全庁的にほかとのバランスもあり、この段階でお答えはできないので、内部で調整して。私からは選考基準に関する点数の公表に関する部分ですが、こちらも今回外部委員を、外部の方を入れた選考の過程というのは、企画部のほうで主導して今年初めて実施するものです。","voiceIndex":132,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その関係を継続させ、長期的に安定したサービスの提供が求められる。品川区の、今回２２施設が全て継続というようなことになっている理由というのも、そのように中身を検討していったら、今申し上げたようなことのために継続性が必要だというようなことになるのではないかと思うのですが、いかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"今回対象となる施設、高齢者福祉課所管施設でいいますと、１４か所あります。１件１件モニタリングの結果を基に、基本の方針、それから基準に照らし合わせて、次期５年間をお任せする指定管理者として適任かどうかということをこの間議論、審議してまいりました。","voiceIndex":135,"id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私が申し上げたのは、これだけ継続というようなことで、２２施設が公募によらず継続ということになっている、そこの中身については、目黒区で規定されているように、福祉施設においては利用者と事業者の信頼関係をつくり上げていくのに相当程度の時間を要するというようなことでしたり、障害者施設についても、高齢者施設についても、専門的知識が必要とされるところであるので。","respondent":"寺嶋福祉計画課長","answer":"それで、全てをここに書き込むということは大変難しいですが、そういったことの趣旨を踏まえて、合理的に判断されるという表現を品川区としては取らせていただいたということで、冒頭述べましたけれども、やはり基本的には公募プロポーザルが原則といった中で、今回一番の肝は。","voiceIndex":137,"id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やるにあたって、やはりなぜやっているかというようなところでは、今申し上げたような規定をほかのところでもつくっておりますので、今回見直すにあたっては、この合理的ですとか、連続性というだけだと、なかなかその文言だけでは分かりにくい部分があるので、ぜひ先ほど申し上げたようなことは、規定の中身も今見直しているということですので、ぜひその中にも盛り込んでいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"定期的にやるものも行いますし、随時行うというものもあります。労務監査につきましては、現時点で私どものところにそういったものを行ったという情報は入ってきておりません。","voiceIndex":139,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうすると、この２２施設が今回指定管理の対象ということですが、この全てで労務監査が１回もされていないということになるのでしょうか。その確認をお願いしたいと思います。","respondent":"寺嶋福祉計画課長","answer":"労務監査につきましては、全庁的に企画部のほうで主導して行っているということで、ちょっと今どの施設がということは申し上げられないのですが、区としてやってはいますが、対象施設が今年どうだったのかなどということは、ちょっと今手元に資料がないので申し訳ないのですが。","voiceIndex":141,"id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのようなものは、あまりにたくさんの指定ですので、１つの指定が初めて指定されるときだったらそのようなことを伺うと思うのですけれども、５年間に一遍のというようなことなので、私はそのような、人的な状況のようなものが分かるような形の資料もぜひ出していただきたいと要望したいのですが、いかがでしょうか。ざっくりで結構です。","respondent":"宮尾高齢者福祉課長","answer":"それから離職率についても同様です。介護職の人材確保に関するテーマですが、それもこちらには記載がございませんけれども、これは私ども、保険者としても大変重要なテーマであるというふうに捉えておりますので、こちらは引き続き様々な支援策を講じながら推進していく予定です。","voiceIndex":143,"id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは５年に１回の指定管理者の選定ということになるわけですから、継続ということではありますけれども、そのようなところについても、区が把握している中身について状況が見える形に、透明性という形になるのですか、そのような見える形にぜひ、資料としても出していただきたいと思うのですが、その点いかがでしょうか。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"今年から試行ということで始めましたので、今後、資料等につきましてもいろいろ検討はなされていくというように我々も考えておりますので、よりいいものができるように努めてまいりたいと思います。選定委員会における点数の件ですが、資料にあります選定委員会の構成、こちらに出席するメンバーが、それぞれこの選考基準に基づきまして、それぞれの施設。","voiceIndex":145,"id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"人件費がどれくらいかかったのか、ほかに何がどうかかっているのかというようなものが見えないモニタリングの資料になっているので、そのようなものも含めて出していただきたいということで、今回は５年に１回の選定ですから、そのような点ではもう少し見える形で、資料についてはご検討いただきたいと思います。これも、何か算定の根拠を改めてお伺いさせていただけたらと思います。","respondent":"寺嶋福祉計画課長","answer":"先ほどモニタリングの資料のお話が出ましたけれども、繰り返しになりますが、今回の選定委員会は、新しい試みということで始めまして、恐らくそれに連動して、モニタリングの資料も選定委員会では大変重要な資料になってきますので、情報も含めてですが。","voiceIndex":148,"id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"確認","question":"２つほどお尋ねしたいのですが、１つは経営基盤ということと、もう一つは人的な体制ということで、経営基盤については後ろの補助資料に様々な収支のいろいろな試算といいますか、載っているのですが、これはもちろん専門家の方が貸借対照表などで確認したのだと思うのですが、ひとつそういった財政的な基盤についてのきちんとした体制が。","respondent":"寺嶋福祉計画課長","answer":"それから人材確保について、これは選定委員会の段階でどうこうという話ではもう、当然手遅れなわけでございまして、通常のモニタリング、もっと言ってしまえば日頃の法人、施設とのやり取りの中で、どういった資源が必要かとか。","voiceIndex":150,"id":"exchange-044"}]},{"id":"topic-05","title":"て、(6)第８１号議案、(7)第８２号議案、(8)第８３号議案、(9)第８４号議案、(10)第８５号議案、(14)第８９号議案","agenda":"て、(6)第８１号議案、(7)第８２号議案、(8)第８３号議案、(9)第８４号議案、(10)第８５号議案、(14)第８９号議案","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それでユニットケアのほうが、モニタリングでそこを見ていないのですが、指定管理料が高くなるとか、そのようなことがあるのかどうか伺いたいと思います。それから高齢者の特養ホーム、今日ここにあるのは三徳会と品川総合福祉センターくらいですけれども、品川区内にはたくさんの社会福祉法人の特養ホームがあると思うのです。","respondent":"宮尾高齢者福祉課長","answer":"ちなみに国はユニット型個室というものを推奨しておりますので、今後はこちらがメインになってこようかと思いますが、多床室も区立の特養ホームにはありますので、多床室を持っているから経営的に不利ということにならないよう支援していくのが。","voiceIndex":169,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、モニタリングを見せていただいたら、ユニットケアのほうの指定管理料が特に高いというわけではなくて、それでも運営はできているということで考えていいのでしょうか。取りあえず結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-046"}]},{"id":"topic-06","title":"令和２年陳情第５６号、加齢性難聴者への補聴器購入費用の助成を求める陳情","agenda":"令和２年陳情第５６号、加齢性難聴者への補聴器購入費用の助成を求める陳情","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ですから、啓発するということと有効性を認識しているということ、だから啓発していくということを言うのならば、やはりそれなりの助成制度を設けて、積極的に推進していくということに、イコール踏み出していくということになっておかしくないのだと思うのです。そのように考えるべきではないかと思うのですけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"それから普及啓発につきましても、我々がすごくいいから調整が必要だということを責任を持って普及啓発ができるかといいますと、これは大変難しい問題でございまして、やはり専門機関がしっかり普及啓発をしていくという重要性を訴えている以上、我々もそこにつきましては。","voiceIndex":206,"id":"exchange-047"},{"speaker":"おくの委員","kind":"質問","question":"この点につきまして、それが有効性を持っているということに関しては、この専門のお医者さんが言われていることであって、その点に関しては疑いのないことではないでしょうか。先日の厚生委員会では有効性に対しては認識しているというように答弁されているのですから、その点を後退させる必要はないのではないでしょうか。伺います。","respondent":"寺嶋福祉計画課長","answer":"こと補聴器に関しましては、それ以外のいろいろな情報も前回の請願の際にご紹介したとおりですけれども、区として責任を持って、補助制度が一番効果的だということを現段階で申し上げることはできないと、このように申し上げているところです。","voiceIndex":208,"id":"exchange-048"},{"speaker":"おくの委員","kind":"質問","question":"もう一つ使わない理由として、補聴器の所有率が日本で低くなっているのは、補聴器を購入する経済的な余裕がないということを２４％の方が理由に挙げているということがあります。これはご認識なさっているのでしょうか。それも伺っておきます。","respondent":"寺嶋福祉計画課長","answer":"２４％という数字がいつの調査か、すみません、私の手元の資料と数字が全く異なるのですが、我々が把握しているところとしては、補聴器を使わない理由の上位として挙げられていないということ、これについては前回の請願のときにご答弁申し上げたとおりです。","voiceIndex":210,"id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、私はこれで耳鼻科の先生と同様の認識だというように言われたので、早期着用については区も同様の認識をしている、早期着用がいいことだということが区の認識でもあるというふうに答弁していただいたと思うのですけれども、そこは違うのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"専門の医療機関の方が補聴器の有効性について認識があるというように言ったということを、我々区としても把握はしているということで、専門家の方がそのように言っているということについては、我々も別に疑うものではないという意味で言ったところで、再三になりますけれども。","voiceIndex":212,"id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"それは、専門家の方々がどれほどそれがいいよと言っても、区はそのような認識には立てないということになるのか、私はそこのところが出発だと思うので、この間ずっと確認をしていたところなのですが、専門の方々が皆さんそのように、耳鼻科の先生が口をそろえておっしゃっているし、補聴器学会の方々も皆さん言われておりますし、そのような専門家の方々がそのように言われても。","respondent":"寺嶋福祉計画課長","answer":"区の認識になる、ならないということを申し上げてございません。専門家の方がそのように言っていることにつきましては、我々も情報としてしっかり受止めているということです。","voiceIndex":214,"id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、耳鼻科の先生方が皆さん、専門家の方々がそろってそのようなことを言っているということは区も認めて、それは否定しないと。ではもしも、区がこれに対して補助制度をつくっていくということになる場合は、何か障害となることはあるのですか。","respondent":"寺嶋福祉計画課長","answer":"そのようなことを言っているということは聞いているといっても、全員から聞いたわけではないので、専門機関が皆さん言っているかどうかについては、申し訳ないのですが、この段階では責任を持って答弁することはできません。","voiceIndex":216,"id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、耳鼻科の学会を挙げて、これは早期着用が有効だというようなことを出していると思います。私は助かるというところまでの補助制度をつくっていただきたいと思うのですけれども、そのようなところで補聴器を使わない理由のトップテンの中の上のほうではないというようなことは、私は理由にはならないのではないかと思うのですが、その点についてもいかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"は繰り返しになりますけれども、しっかり使うということ、調整する、トレーニングするということを専門機関、それから機器メーカーのほうでしっかり言っていただくことで、我々も定期的に医師会等と連絡会等の運用もありますので。","voiceIndex":218,"id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この補助制度は、前回は９区というように書かれていたのですけれども、今１１区まで、今年度さらに広がっているのです。認知症の問題は本当に大問題だと社会的にも言われておりますし、高齢者の生活の質が本当に大きく変わるという、これは補聴器の役割だと思いますので、ぜひ、今のところはということですので、これが最後というようにならないうちに、補助制度をぜひつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-054"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願い致します。前回にも担当課より説明がありました。定期的な検査、調整がとても重要な器具であることを実感しています。ですので、まずは専門機関にて正しい理解を啓発していくことが必要だと思いますので、本陳情に関しましては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":223,"id":"exchange-055"}]},{"id":"topic-07","title":"令和２年陳情第５９号、生活介護の事業所運営法人を現在より減らすことがないことを求める陳情","agenda":"令和２年陳情第５９号、生活介護の事業所運営法人を現在より減らすことがないことを求める陳情","exchanges":[{"speaker":"渡部委員","kind":"提案","question":"本会議の前の日ですか、この陳情が出てきたときに、確認をして、その段階では品川区の福祉に関することで、大枠を捉えてそのようなお話だと思っていたのが、木曜日でしょうか、共産党のおくの議員の一般質問の再質問の中で、５つの障害者団体の代表の方からも、現事業者の継続を求める陳情が出されておりますという発言がありました。４０名の議員全員に宛てて継続を求める手紙もということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":235,"id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この指定管理者の公募については、９月２４日の厚生委員会で報告があったわけです。決まったところで、ここの議会の中でどれほど議論しても、もうそこで決まってしまうわけですから、決めるにあたってこの思いを聴いてほしいと。決めるにあたって、この切実な思いを聴いてほしいのだということが今回の陳情だと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問","question":"ほかの会派のというお声があったので、私のほうも。ですから内容に配慮して、議会のルールとして、これについて審査してはいけないというようなルールは私はないと思います。先ほど理事者のほうからあのような説明がありましたけれども、本当にそれでいいのですかという感じを、私は受けています。正直に言うと。ただ、恐らくそれは……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"ただそれは共産党が言っただけであって、公式に結びついたわけではないですから、私は別に、それとこれが関係ある、それは公式に議会として認めたわけではありませんので、これは大変気を遣って、恐らく相当気を遣った文章だなと、私は受止めさせていただいています。確かにおっしゃるとおり公募と読めないこともないですよ。そこはできないということではないと、私どもは考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-059"},{"speaker":"西村委員","kind":"意見","question":"今公募中ですので、事業者選定に影響を与えるということと、公正な選定のため、倫理上私たちの考えは控えるべきではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":240,"id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"意見","question":"現状、指定管理の選定を進めているところなので、委員としてそれに関して、現時点で可とも不可ともということを話すことによって、何らかの影響が、自分ではないと思って発言しても、結果として出たとしたら、やはり自分で責任を持つということになりますから、ここでの議論はできないと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":241,"id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今まで、愛成会を含めて、ここにも名前が書いてあるから申し上げますけれども、そこについての様々な、議会においての内容が不十分ではないですかというご質問を私は一般質問でさせていただきました。このような質問もありました。ただ一般質問ですから、私どもは一部しか質問できなかった。今回ご答弁がないということですから、意見表明のような形になっていますけれども、最後に１つだけ申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":248,"id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"９月２４日にここで公募の報告がありました。それで子ども発達相談の需要が高まる中、新たな施設整備こそ必要ではないかと質問したときには、さらに荏原地域に考えています、またさらに誘致もしますというようなことで答えられているわけですから、ぐるっぽの責任だけではないのではないかと思うのですけれども、なぜそこのところを説明されなかったのか、その点について伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その説明だけだと分からないわけです。だけれども、実際は需要がこれだけ伸びていて、このような状況で取組んでいますというところと、区としても、今後新たな施設が必要だというように考えていますと、私はそのように答弁していただきたいと思いますけれども、どうでしょうか。その思いを受止めていただきたい。そのような場をつくっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"事業所の整備につきましては、現在も進めているところです。利用者への対応につきましては、必要性があると判断した場合は説明をする機会等を設けたいと思います。","voiceIndex":253,"id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひやっていただきたいということでお願いしたいと思うのですが、いかがでしょうか。そのようなところでは、選択肢が少ない、そしてその人に合った事業所を選べるような、そのような事業所をつくっていくということが必要ではないかと私は思うのですけれども、そこのところはどう捉えられているのか伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"区民への説明につきましては、先ほどもご説明させていただきましたが、必要と判断した際に対応したいと思います。それから事業所につきましては、現在生活介護ではございませんが、そのほかの事業で補助金等を出したりして誘致を図っているところです。","voiceIndex":255,"id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのような点では、その育成会の手紙でも、現状維持ではなく福祉の向上を考えて福祉を変えるという選択をしていただいて、品川の福祉は変わっていけると期待をしたと。そして実際に１年間たって、期待に十分応えていただいた、そのような事業所だったというように皆さんから訴えられているわけですけれども、そこのところは区としてどう受止められていますでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"指定管理者候補者を選定する上におきましても、評価の１つになってくるものだと考えております。その上で、事業者選定にあたりましては、地域生活の支援拠点という施設の設置目的に沿った運営ができるかどうか等を総合的に評価することも必要であると考えております。","voiceIndex":257,"id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そして施設を利用したことのあるご家族で、悪口を言う方はいませんというように書かれています。私はこのようなところを、本当にしっかりと当事者の立場に立って、区としても受止めていただきたいと思うのですけれども、この当事者の思いを区としてどう受止められているか、その受止めについてちょっと伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"当事者の思いということですけれども、施設に対する評価として受止めております。","voiceIndex":259,"id":"exchange-067"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これだけ切々と訴えられていることに対して、どう受止められているかということを伺っているのに、評価として受止めていますという一言だけで済まされるでしょうか。ちょっとその点についても伺いたいと思います。評価として受止めますというだけではなく、その評価としてどう受止めたのかをお聞かせいただけたらと思います。","respondent":"築山障害者施策推進担当課長","answer":"あまり言いますと公募のほうに影響が出ますので、コメントは差し控えたいと思うのですけれども、評価というところでいうのであれば、利用者に沿ったきめ細やかな支援をされていらっしゃるなというところは感じているところです。","voiceIndex":261,"id":"exchange-068"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はこのことを障害者福祉を進めるときの基本にすべきだと思うのですけれど、品川区としても基本に据えていただきたいと思いますが、いかがでしょうか。そして施策の検討や決定にも、当事者家族の声、先ほどもこれを一番に考えるべきだということがありましたけれども、そのことをどう位置づけ、反映させてきたのか、また、これから反映させようとしているのか、伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"委員の言っていることは当然の考え方だと考えております。その上で、施設の設置目的に沿った事業運営ができるようにということで、取組んでまいりたいと思っているところです。","voiceIndex":263,"id":"exchange-069"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから一般質問の中で、部長のほうから利用者の満足度も選定にあたっては重要な指標ということで答弁がありました。経営や財務、運営実績、運営方針等々は書かれているのですが、満足度については、利用者、家族の要望、願いをどのようにはかるのか、そしてどのように審査に反映させていくのかという点について、具体的にどうされるのかお聞かせいただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"利用者の意見につきまして、審査会の前に実施という予定はございません。ただし、８月、９月にアンケート調査を行っておりますので、そういったところで利用者の満足度というところは、区として把握をしています。","voiceIndex":265,"id":"exchange-070"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのようなところはぜひとも受止めて、選定していただきたいと思います。それと今回の公募、選定の中には、審査会と選定委員会というものがありますよね。なぜ選定委員会ではなくて、２つの委員会があるのか伺いたいということと、２つの委員会に別々の外部委員を２名ずつ入れるということで、合計４名の外部委員を入れるということになるのか、その点についても伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"選定につきましては、指定管理の区のガイドラインに沿って対応しているものです。それから外部委員につきましては、複数名入る予定ですけれども、現時点での詳細については控えさせていただきたいと思います。","voiceIndex":267,"id":"exchange-071"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"すみません。今ちょっと聞き取れなかったのですが、２つの委員会に２名ずつで、合計４名入るということで、今答えていただいたのでしょうか。違いますか。","respondent":"築山障害者施策推進担当課長","answer":"委員構成に関わることにつきましては、現在公募期間中ということで、回答のほうは差し控えさせていただきたいと思います。","voiceIndex":269,"id":"exchange-072"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"外部委員を入れるということは、たしか報告をいただいたと思うのです。その辺は別に言ったからといって、別に名前を教えてとは、名前を教えられないということはこの間から重々聞いているのですけれども、前は言っていただいていたのですが、今回は言えないということで言われておりますけれども、２名ずつ入るかどうかと、その辺までなぜ言えないのですか。","respondent":"築山障害者施策推進担当課長","answer":"構成に関することの詳細はお答えできませんが、審査会、選定委員会ともに外部委員が複数名入る予定になっております。","voiceIndex":271,"id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は今回５つの障害者団体、品川区の障害者団体の代表の方々の５つの団体の皆さんが、これだけ名前を連ねて陳情を出されたということが、区政史上初めてではないかと思うのです。私はこの障害者団体、当事者の皆さん、ご家族の皆さん、その思いをしっかりと、品川区として受止めていただきたい、このことを強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"意見","question":"継続です。理由は先ほど述べさせていただきましたが、本来であれば本当にこのとおりだなと私どもも考えていますが、先ほど渡部委員からもありましたとおり、公募の期間ということもあるので、それも配慮した上で継続ということにします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":280,"id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3582#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":83995,"voices":286}},{"id":"r02-20201130-8","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"建設委員会","time":"午前１０時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第９２号議案、北品川一丁目地内特別区道路線の認定","agenda":"第９２号議案、北品川一丁目地内特別区道路線の認定","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"必ずこれ、道路を認定して、いつ頃こうやって道路になるのか。一応、お話では２０２７年頃ということだと、それから解体があって、大体２０３０年頃ではないですかというのが我々の理解なのだけれども、その理解でいいのかということ。それから、先ほど区道III－２０号の付け替えという話があったのだけれども、これは付け替えで、道路自体は大体面積的に一緒なのかという話。","respondent":"稲田土木管理課長","answer":"面積的な話がございましたけれども、区道III－２０号という既存の路線ですが、ずっともう少し下のほうから来ておりまして、下のほうからずっとつながっている路線です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど言ったように、事業完了後というのは、立体化の事業完了後だろうから、２０３０年頃と我々は理解しているので、それでいいのかということと、あと、地域の方からお話があったから、先ほど言った清水横丁の話。だから、多分、ここの角は、今、計画のところに入っていないけれども、これはこれで地域の方々と話してこういう形になっているという理解でいいのかというところだけお願いします。","respondent":"中道まちづくり立体化担当課長","answer":"清水横丁につきましては、都市計画決定の際にもいろいろと意見交換をいただきまして、道幅であったり、景観であったりを配慮してほしいという言葉をいただいてありますので、地域の方の意見を踏まえまして、また整備の内容等については検討してまいります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"今までも幾度かご説明があったと思うのですが、確認も含めて、重複になるかもしれませんが、お願いいたします。黄色い部分というのは現状どうなっているのかということと、結局、最終的には区道III－２０号というのはなくなるわけであるので、ここはどういう状況になっていくのでしょうかということ。それから、６ｍのところで、歩道が２ｍ。","respondent":"中道まちづくり立体化担当課長","answer":"今現在、詳細については、東京都が検討中です。６ｍの道路につきましては、今、車道が４ｍ、歩道が２ｍです。車道上に自転車のレーンを設置するかというところにつきましては、今現在、調査というか、詳細な検討をしています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"自転車のところは検討中ということなのですが、やはりそんなに広い幅ではないと思うので、ただ、分離をきちんとして、交通事故が起きないような形をぜひ検討していただきたいと思います。すみません、１点、答弁漏れというか、黄色いところは今どうなっているのでしょうかという。今どういう状況になっていますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"線路。今、どういう状況になっているのですかというのを。","respondent":"中道まちづくり立体化担当課長","answer":"黄色い区域の部分につきましては、今現在、線路上というところで、京急が用地を持ってあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"今、交通広場を整備していくという中で、区道の認定というのも出されておりますけれども、この交通広場ができることによって、やはりまちの方々が心配されている旧東海道の道幅ですとか、先ほども少しお話がありましたけれども、横丁がきちんと守られるのか、そこを伺いたいのと、交通広場になると、つまりは道路になるということで、地域の方はその場所を気軽に使いたいというお話が出ていますけれども。","respondent":"中道まちづくり立体化担当課長、稲田土木管理課長","answer":"現在もこちら、町会長または区民の方々と意見交換をして、こちらのほうの駅前広場をどういう広場にしたらいいかと、地域の方を併せまして、検討している最中です。一般的に道路の使用についての手続きの話というのですか、おまつりやイベントや、そういうことで道路を使用しようとするときは、交通管理者の警察の許可が要るというところでございまして。","voiceIndex":16,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"景観については、今、意見交換をしているということですけれども、実際に今回の右側の広場のところというのは、建物が旧東海道から広場のところまでかかっている状況のところが多くありますので、そうなると、そこの建物が除却されてしまって、旧東海道の景観というのが壊されてしまうのではないかと思うのですけれども、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"建物が除却されて空間がオープンになるのではないかですが、そこの境につきましては、生け垣や、また、そうした壁等のしつらえ等で景観を守っていきたいです。そうしたことも踏まえまして、今現在、地域と意見交換をしながら進めているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"意見交換をしているというところはいいと思うのですけれども、やはり建物がなくなることで景観が変わってしまうということになりますので、そこは守れないのではないかと私は思っております。今回、こういった区道の認定の話が出てきましたけれども、この前に都市計画審議会で審議されて、意見書の募集なども行われておりますが、意見書の賛成・反対の数というのがどうなっているのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画決定を取る際に、この事業、２回、意見をいただいてあります。当初は、２０通、５８名の方から、変更のときには１５通、１６名の方からいただいているです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"意見書のほうは、たしか最近行われたものでは、賛成２件、反対十何件という感じだったと思うのです。その中で、つまりは、反対している人のほうが多いということだと思うのです。やはりそうしたところでやっていくということが必要だと思いますので、そういった住民の声をしっかりと聞いて反映をさせていくということがまちづくりの基本だと思いますので、ぜひそのように進めていただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"先ほどの変更のときの意見書の数、賛成・反対の数ですが、賛成が２通、反対は１２通、その他といたしまして１通あります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"改善してほしいと思います。そして、スケジュール感なのですけれども、もう一度確認させていただいてもいいですか。ここには、都市計画道路事業認可と認定のことしか書いていないので、先ほどほかの委員から解体とか完成の時期とかも出ていたのですけれども、私の調査漏れなのか、そういったことがもうどこかで報告されていたのかというところも併せて伺いたいと思います。そして、なぜ今認定が必要なのか。","respondent":"稲田土木管理課長","answer":"それともう一点、なぜ今の時期かということですが、これは事業認可が４月に下りておりますので、速やかにというのですか、そういう形でこのような手続きをしているものです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"その根拠がもしあれば、お知らせいただきたいというのと、あと、これから認定をするということは、この道路にしていきたいということですよね。ただ、今、感染症が広がる中で、シーリングがかけられているときに、なぜこのタイミングなのか。区としても、今この認定を出す時期なのかというところもお知らせいただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"こちらの事業のスケジュールですが、今年の６月３０日の建設委員会での報告で、事業決定をしましたので事業を進めるというところで、地域に対して事業の概要等を説明した経緯があります。","voiceIndex":28,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"都のほうでも、工事とかは、この感染症に予算がすごく使われるということで削減していくということだったのですけれども、では、都としてもこちらのほうは進めていくということなのですか。そのスケジュール感を先ほど伺ったと思うので、そちらもお知らせいただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"この事業を進めるか進めないか、まず１点目のご質問ですけれども、進めてまいります。東京都も中止する考えはないというところは確認しています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"今のご答弁からも、やはり道路としての必要性というのがそれほど伝わらなかったというか、広場とにぎわいを求めるためにとしか思えなかった。この道路を造ったら、学生の滞留が解消されるのですかというところと、あと、車ですよね。というところとかも、利便性が、広場を造ってにぎわいがというところが主だったのかというのを思ったのですけれども、そこら辺を確認させてください。","respondent":"中道まちづくり立体化担当課長","answer":"東京都が行います連続立体交差事業で、こちらにあります踏切が３か所解消されます。その３か所が１時間に遮断量が４０分以上の、いわゆる開かずの踏切と言われるものの解消になります。","voiceIndex":34,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"タクシーのお話も、前の議事録とかを追ってもお話が出てきたのですけれども、それほどここでタクシーを利用するというのが、地域でもあまりないのかというのは感じていまして、地域の方からもそういうお話を伺っています。立体化が地域から求められているのはすごく分かるのです。改めてそこの部分をご説明いただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"今の流れでいきますと、来年度には用地を譲っていただける方がいらっしゃるような傾向がありますので、先ほどご説明いたしました国費の申請をする前に、道路をきちんと位置づけたいというところで、今、行政手続きを進めている最中です。","voiceIndex":36,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"今回、区道にするということですと、財源がどうなるのかということで、区が施工して予算をつけていくのかどうかというところを、先ほど少し補助金の話もありましたけれども、財源がどうなるのかというところを伺いたいと思います。先ほど広場使用のところでは、警察の許可が要るということで、そうすると、住民の方が気軽に使えなくなってしまうのではないかと思うのですが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長、稲田土木管理課長","answer":"財源ですが、事業主体が区ですので、まず区がそちらのほうのお金を用意する。その中で、国費が約５０％、また都費が約２０％ということで、約７割の補助金を入れて事業を進めていきたいと考えています。委員のおっしゃっている使い方がどのようなものか、はっきりしませんけれども、普通に道路は皆さん使ってもらって結構ですので、普通に広場としての使い方を区民の皆さんがしていただく分には、特にそういう許可とか。","voiceIndex":40,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"今、普通に使う場合は許可は必要ないということでしたけれども、普通というのはどういうことですか。おまつりとか、そういうときに使う場合には許可が必要だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"認定については、今なぜこのタイミングなのかというところも、やはりお話を伺ってもよく分からなかったというところと、あと、道路にしてからの利便性というところも分からなかったというところで、ここの認定については反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"}]},{"id":"topic-02","title":"令和２年陳情第６０号、「大井町駅周辺地域まちづくり方針」のＣ地区に関する陳情","agenda":"令和２年陳情第６０号、「大井町駅周辺地域まちづくり方針」のＣ地区に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この中で、防災面の課題ということも言われておりますけれども、区が捉えている課題は何か、伺いたいと思います。それと、この辺りは昔からの再開発の動きがありましたけれども、その際に、以前の数十年前のときに再開発の準備組合ができたということで、まだそれは解散していないという話も聞いているのですが、区の認識として、この準備組合というのは残っていると考えているのか、伺います。","respondent":"多並都市開発課長","answer":"ここの高層ビルという先ほどのキーワードがありますけれども、そこにつきましても、この勉強会の中で５回開催されておりますけれども、この勉強会の位置づけとしましては、地域の方がこれからまちづくりを進めていく上の手法がいろいろと幅広くあるので。","voiceIndex":59,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"やはりそういった中で、この陳情の中でもありますように、「まちの良さを残しながら改善を図る手法」というのが、私も必要だと思います。そうしたよさを残しながら改善をしていく手法というのはどういったものがあるのか、伺いたいと思います。実際にこの再開発の場合、損失が出たときは地権者が負担する仕組みとなっているのか、伺いたいと思います。そのまま残ってしまうのか、伺います。","respondent":"多並都市開発課長","answer":"もう一つの、例でありましたように、市街地再開発事業が事業として、先ほど破産というお話がありましたけれども、そのようなことがないように、まず事業の最初のスキームであったり、検討していくことが重要でありますけれども。","voiceIndex":61,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"地域の皆さんで話していくことが重要ということがところどころで言われているのですが、まず、仕組みとして、再開発の仕組みというのが、事業が成り立たなくなった場合、損失が出た場合、地権者が負担するということがあるのかということと、あと、借金が既にある方たちが再開発に巻き込まれた場合、この借金がどうなってしまうのかというところで、仕組み上の話で伺いたいのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"そのときにご自分がお持ちの、今までの資産の借金についてもどうするかという、もちろんそれもなくなるわけではありません。借金がなくなるわけではありませんから、そういうのも全体を含めて皆さんで考えていただくというのが答えかと思います。","voiceIndex":63,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"つまり、借金も残ったまま、もし事業が破綻してしまった場合は、地権者の方が負担する可能性があるということだと思います。この間、再開発というのが、合意がなくとも進められているという実態がありまして、大井一丁目南第１地区ですかね、そのときには合意していない方が多くいらっしゃったと思うのですけれども、本組合の設立をしたときの地権者数と同意人数を伺いたいのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"要するに、賛成だ、反対だというわけではなくて、やはりまちづくりというのは非常に難しい部分もありますから、それをまず知っていただくということで、みんなでそういうのをやっていただく段階だとご理解いただければと思います。","voiceIndex":65,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり住み続けたいという方もいらっしゃるということがありますので、この陳情にもあるとおり、真の意味で住民主体のまちづくりということで、住民合意のもとで進めてほしいということですので、進めたいことも含めてですけれども、よりよいまちにしていくと。まちのよさを活かしながら進めていくということでやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"区のほうにこの陳情について何か伺うというのはとても変な形だと思うのですけれども、先ほどから何回も皆さんで考えていただくということをお話しされていたので、やはりこの地域の実情等を踏まえた方針の見直しというのは、区のほうも認めていらっしゃると思うので、陳情にはぜひ皆さんに賛成していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"多分、ここの地域は、そういう対策を取らなければいけないという地域という認識でよろしいのでしょうか。それについてはどう考えられるかということ。ですので、こういうのは、まず１つは、区の関与というのがどこまでできるのですか。分からない。それから、最後のところ、下のほうです。ただ、やはり住民にしてみれば、Ｃ地区というのが決められていて、それは品川区がＣ地区と囲ったわけではないですか。","respondent":"多並都市開発課長","answer":"ここにつきましては、耐火、いわゆる構造物の防災上の課題があるような建物の割合につきましては、大井町周辺の他地区ですと６０％くらい耐火の構造物がある中で、このＣ地区については４割程度ということで。","voiceIndex":75,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、先ほど来、委員からの話で、「思います」とか、賛成・反対とかという、多分に主観の混じられた質疑応答がありまして、私はそのように受け取りましたので、客観的にお話を聞きたいと思いますけれども。これ、おおむねどのくらいの期間、今までやられているのか。改めて教えてください。","respondent":"多並都市開発課長","answer":"勉強会のほうが、令和元年５月から第１回目で、令和元年７月、９月、１１月、あと、令和２年１月で５回ということをやられていると認識しています。心配する会が令和２年２月、３月ということで、２回やられているということで認識しております。","voiceIndex":79,"id":"exchange-025"},{"speaker":"大沢委員","kind":"意見","question":"ということは、まだその中では意思の疎通というか、心配されている方は分かりますが、その中では双方の意思の疎通が十分に行われていないということが見受けられるのですけれども、そこのところをどのようにお考えになりますか。","respondent":"多並都市開発課長","answer":"まちづくり勉強会の事務局の方は、まだどの手法だと選んでいる前の段階ですから、その段階ではないというご説明をして、行き来をしているような、そういう認識で区としては思っているところです。","voiceIndex":81,"id":"exchange-026"},{"speaker":"大沢委員","kind":"確認","question":"それだと、ここのところの方針については、かなりの弾力性というか、遊びがあると考えます。その中で、再開発の手法については、まだこれからの双方のまちづくりに対する考えを聞きながら決めていくわけであって、ここに言う、都市再開発法で定めた権利変換なるものに対して決まったというわけではないということで、そこは一回確認させてください。","respondent":"多並都市開発課長","answer":"今、委員のお話のとおり、まさにそのとおりで、権利変換というのはもっと本当に先の話で、まだその本当の前の前の段階とご理解いただければと思います。","voiceIndex":85,"id":"exchange-027"},{"speaker":"大沢委員","kind":"意見","question":"となると、基本的にまだ始まったばかり、初期段階で方向性が決まっていないということですので、初期段階であれば、今後の様々な調整方が必要になってくるわけだと思います。その中でいずれかはやってくるだろう双方の意思疎通も含めた会合なるものも必要になってくると思うのですけれども、そこのところの段取りはどのようにお考えになりますか。","respondent":"多並都市開発課長","answer":"今、皆様にひと通りこれからのまちづくりの手法を勉強していただいていますので、その次の段階として、ほかの地区の例では、まちづくり協議会だとか、そこの中でまずは話し合っていただくことになるかと思いますけれども。","voiceIndex":87,"id":"exchange-028"},{"speaker":"大沢委員","kind":"確認","question":"先ほど来、課長のご答弁にもありましたように、あくまでも助言、それなりの方向性を導くために、この双方の勉強会にそのような考えのもとに出席をされ、よしとする方、それに対して違うという方の平らけく意見を聞かれているということが現状ですね。もう一回確認させてください。","respondent":"多並都市開発課長","answer":"委員のおっしゃるとおり、区としては、双方、いろいろな方のご意見ということで捉えているところです。","voiceIndex":89,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"今だからこそこういう議論が出るべきだと思います。いろいろな手法を選んでいる段階というご説明があったのですけれども、何でこの勉強会が選ぶのですか。今、そのご答弁を聞いて、私、やはりこれは地域の方たちが主体になっていないではないですかと思って、思わず聞いてしまったのですけれども、まさかそうではないですよね、というのを確認させてください。確認させてください。","respondent":"多並都市開発課長","answer":"協議会と先ほど言ったのは、一般的にほかの地区でいえば、そう進むことが一般的で、それも含めて皆さんで考えることですから、そういうご理解でいただければと思います。ただ、そういう段階というのですかね、というご理解という説明を先ほどさせていただいたところです。","voiceIndex":93,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"選んでいる段階ではなくて学んでいるということで、分かりました。ですので、勉強会をされている方たちはいろいろな手法をご存じで、それを学んでいるということだと思うので、それが地域の方たちとも共有されて、それで本当に地域の方たちとともに進むまちづくりに、先ほど冒頭の説明にもあった、その地域主体でのまちづくりが進むように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは、必ず地域の課題を解決するためにはどのような手法が必要だ、それこそ第一種市街地再開発事業のお話も、もちろん先ほど来出ているけれども、では、第二種にすればいいのか、共同化にすればいいのか、様々な手法があるわけで、それは地域の方々が、先ほど来、一緒にともにやってもいいのではないですかという話もあったけれども、品川区はオブザーバーで出ているわけでありますから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"本日結論を出していただいて、不採択でお願いします。理由は、先ほど来、都市開発課長とのやり取りの中で、区ができる限りの地域課題、あるいは地域意思、住民意思を起こすべく取組みをしております。よって、ここにおきまして採択をすることによって一定の方向性を出すことについては、反対をいたします。よって、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-033"},{"speaker":"若林委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。品川区の活力の源であり、また、そういったものを今後ぜひ創造していってほしい。機会をなくしてしまうということにも私はつながると思いますので、そういう意味では、区の方針は現状のまま見直しはしないで、Ｃ地区の皆様の意見を闘わせたり、議論をしたりという機会をしっかりと継続したほうがいいかと思った次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、今、いろいろとお話もありましたけれども、やはりまちづくりというのは住民合意が前提でありますので、まちのよさを活かした修復型という手法で進めていくのが私たちもいいと考えていますので、これはそうした中で住民合意で進めていくということを今回も求めている陳情ですので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張します。先ほど来、お話があったように、やはりこの陳情で訴えているのは、今、地域主体の方針となっていないということから、地域の事情等を踏まえた方針の見直しの要望が出されています。そして、丁寧に議論する必要があると私たちは考えていますといった、議論を求めているので、私は本当にこれは採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出して、採択でお願いします。いろいろ議論して、区の意思も確認をしたわけですけれども、陳情の趣旨の中のまちづくり方針というところが、やはり住民サイド、今回の心配する会の方々と区が言っていることが少しずれている部分があると思うのです。今後の対応も含め、柔軟な対応と、それから、区の考え方をさらに示していただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"先ほどのご説明の中の、高架下貸付可能面積のところで、高架下の検討委員会が立ち上がって議論がされるといったお話があったと思うのですけれども、その検討委員会のメンバーについて、都と区とというお話があったのですけれども、ほかにどのようなメンバーで構成されるのかというところをお知らせいただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"詳細については、今後協議ということになってきますが、一般的に、東京都、区、鉄道事業者、この３者で構成されます。","voiceIndex":112,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"今後ということだったのですけれども、この検討委員会が立ち上がった後の検討状況というのは、基本的にこれまでは公開されてきたのか、今後されるのかどうかというところとか、お知らせいただきたいと思うのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"検討委員会の公開についてですが、そちらも踏まえまして、今後調整ということになっていきます。今までの経緯につきましては、現在、把握はしてございません。","voiceIndex":114,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"上位計画のところをお聞きしたいのですが、この関係性なのですけれども、東京都の都市整備局が策定したものが上位ということなのですが、それを基にして品川区まちづくりマスタープランというのができたのかという、その上下関係というのか、それを知りたいのですけれども。そういう場合は、品川区から東京都に申入れをしてという形ができるのかどうか。その辺はどういう仕組みになっているのでしょうか。","respondent":"鈴木都市計画課長、中道まちづくり立体化担当課長","answer":"東京都の計画と区のマスタープランの関係性ですが、当然、鉄道の立体化にあたっては、まずは東京都が東京都内全体の計画のようなものを持っていますので、その中身を踏まえてマスタープランで位置づけていくですが、ただ。こちらのほうが、２０２５年度までに重点的に対策を実施すべき踏切という位置づけです。","voiceIndex":117,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"今、踏切の中で２０か所というお話がありました。全体ではどのくらいあるのかなと思うのですけれども。その辺の力関係も含めて、やはり強く言ってもいいのではないかという部分があるのですけれども、例えば、十分に聞いていただいているのですということなのか、まだまだ十分ではなくて、品川区の現状をもっと伝えて、それを酌み取っていただきたいという状況なのか、その辺はいかがですか。","respondent":"中道まちづくり立体化担当課長","answer":"鉄道事業者や東京都との交渉ですが、そういった意見交換をする場というものが年間に幾度か設けられていたりとか、今現在、先ほど言いました重点踏切をまず解消というところで意見交換はしていますので、そういった中で、特に上下関係というわけではなく、同じ方向を向いて。","voiceIndex":120,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"例えば、横須賀線とかは乗り入れが結構多くなってきていて、開かずの踏切というのが増えてきているのです。見直しをある程度するという仕組みがあるのか。鉄道事業者も経費もかかることなので、その辺の調整というのは、東京都がやるのだろうかと思うのですけれども、どのようにされているのでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"戸越公園駅を例に挙げますと、もともとはシステムの改築とかで解消する方向性でいたのですけれども、先ほど説明いたしました生活道路のボトルネック踏切というところで、連続立体交差事業の方法で踏切を解消していこうという形で、手法をその都度。","voiceIndex":122,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"戸越公園駅のところで伺いたいのですけれども、交通遮断量が示されておりまして、差し引きで車が１,３３６台になるのかと思うのですが、その上に歩行者等ということで、１１万３,６８０台（人）ということになっていますけれども、歩行者と自転車の数、内訳が分かれば教えていただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"そういった形で、今ここに書かれているのは原則であって、また検討会の中でいろいろと柔軟に活用していくです。","voiceIndex":125,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"ピーク時の遮断時間というのがあるのかないのかというところもお聞きしたので、後でご答弁いただければと思います。今回の一般質問でも取り上げさせていただきましたけれども、そこのところはどのように考えていらっしゃるのか、伺いたいと思います。今、戸越公園駅のところは調査中ということで、事業効果等を検討しているということも書いてありますけれども、今の検討状況がどうなっているのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今現在調査中ですが、東京都のほうで、こちらの連続立体交差事業を実施する費用対効果であったり、詳細設計をしまして、実際のそこの工法選定、地下であるのか、高架であるのか等、今現在調査をしている段階で、それを踏まえまして。","voiceIndex":127,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"交通量のところなのですが、私が言ったのは、車の交通量が商店街のところで増えてしまうと困るということで、生活道路のボトルネックになっているので、歩行者は当然より通りやすくなると思うのですけれども、車の交通量が増えてしまうということにもなりかねないと思うのですが、そこはどう考えているのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今、ここでは補助２９号線のお話がありますが、またそれは延焼遮断帯機能を形成するという目的のために東京都が進めている事業です。","voiceIndex":129,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここは日頃車が少ないところになりますので、そういった商店街を残していくということが必要だと思うのですけれども、歩行者の方のボトルネックになっているというのは、以前から言われておりまして、６か所が解消するということで、立体化は、安全のためにも、スムーズな生活を送っていくためにも、ぜひ進めていただきたいと思いますが、そこと一体に駅周辺で行われている再開発を進めていくということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えていただきたいのですが、今お話を進めている、戸越公園駅のほうは私はあまり詳しくないのだけれども、京急の部分については、地元では３０年来ずっと要望してきたことであって、国会議員にもお願いをしたけれども、当時は技術的にもなかなかできないというようなことがあったりして、やっとここへ来て念願が叶う。確認したいのは、駅をこうやって立体化をやるのだと。","respondent":"中道まちづくり立体化担当課長","answer":"そういったことを踏まえまして、今、東京都では、連続立体交差事業を進めていくにあたりまして、地域の状況がどうなっているのかというところで、そこで一つ駅前広場というものを地元区はどのように考えているのかというところが、全体を事業を進める中で一つの条件といいますか。","voiceIndex":133,"id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"意見","question":"駅前広場というと言葉が微妙になってしまうから。駅前広場は、北品川駅も９９％の人は賛成だと。それが、交通広場だといったら、逆に９割くらいの人が反対になってしまった。それは違うだろうと。そうしたら、その次に、これは交通広場なのだという話になって、いきなり９割くらいの人が反対。交通広場という位置づけ、これも必須だよねということを聞いているので、そこをもう一回答弁してほしい。","respondent":"中道まちづくり立体化担当課長","answer":"今後、地域におかれましても、やはり駅前広場という一つの単語だけですと誤解を招くというところもありますので、交通機能を持った広場であったり、交流機能、にぎわいを創出する機能を持った駅前広場といった形で、柔軟に説明を工夫してまいりたいと思います。","voiceIndex":135,"id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど来、地域とともにやってくださるのはいいのだけれども、どうしても風穴が開けづらいのが、高架下。今、立体化になっているところは、駐車場だとか、いろいろな店舗も入っているのも事実なのだけれども、ぜひそういうところを地域として、せっかくここは品川区の区道でもあるし、そういういろいろなことができないかと思っているのだけれども、そこら辺の点はどうお考えになるのか。","respondent":"中道まちづくり立体化担当課長","answer":"もちろん駅前ということになりますので、そこににぎわいを生むような施設というのは、区としても要望していきたいと考えています。","voiceIndex":137,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"でも、ご説明の中では、都では、地域の方たちが求めているかどうかの確認でいいといったご答弁だったのかというのと、それと、必須なのかどうかというのになると、法的に定められて広場を造らなければいけないというものになっていくのかという認識なのですけれども、どちらなのかという確認をさせてください。","respondent":"中道まちづくり立体化担当課長","answer":"区としましては、戸越公園駅を例にしますと、やはり区はそこに６か所の踏切がありますので、また踏切事故もあるというところで、そこを解消していきたいというところで、昨年度、まちづくりビジョン基本計画編というものを策定いたしまして、そういった連続立体交差事業。","voiceIndex":140,"id":"exchange-050"},{"speaker":"田中委員","kind":"意見","question":"交通広場と駅前広場の使い分け、駅前広場は行政用語ということで、区民の方が誤解しやすいといったことから交通広場にして、バスとかも通るイメージをしてもらうといったことだったのですけれども、本当に２つの名前が出てしまうと混乱してしまうので、統一していただければうれしいです。もし違うというならば、もう一回ご説明いただければと思います。ごめんなさい、私、理解ができていなくて。","respondent":"中道まちづくり立体化担当課長","answer":"ですので、今後、そういった形であれば、交通機能、あとはにぎわいを持った、両方の機能を持たせた駅前広場とか、少し表現の仕方というのは工夫していきたいと考えています。","voiceIndex":142,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"申し訳ありません。資料の２枚目の右側に「【参考】駅前広場の役割」というのがあって、要は、場所によっていろいろと目的を考えて造っていきますということなのだろうと思うのです。すみません、先ほど議案審査をした北品川駅のほうで言うと、ここは何になるのですか。だから、そういう意味は分かるのですけれども、北品川駅の例で言うと、どういうイメージをすればいいのでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"これが全部そこに入るかどうかというのは、今後また地域も含めまして、私たちも詳細に検討はしていきたいとは思うのですけれども、今、そういった交通と都市の機能２つを併せた駅前広場の事業をしていきたいです。","voiceIndex":145,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"そこまでご説明いただかないと理解できなかったと思っているのですけれども、誤解されるというのが往々にしてあると思うのです。すみません、理解力がなくて申し訳ないのですけれども、今やっと理解できた状況なので、これからもご配慮いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-053"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"確認","question":"２日目のこんの孝子議員の災害対応についてのところで、災害のときの外国人向けの情報発信についての質問があったと思うのですけれども、その中で、要配慮者と外国人への情報提供を今後どのように図っていくのかという部分を伺いたいと思います。特に外国人の方に向けてが、当事者の方への聞き取りが行われていないといった答弁があったと思うので、そこの部分を確認させていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":42462,"voices":156}}]);
